return {["scripts/quests/windurst/SOB3_Inspectors_Gadget.lua"]={["Path"]="scripts/quests/windurst/SOB3_Inspectors_Gadget.lua",["SHA256"]="426243d89e91287e068792ece59507f03b427af9db862faee24a868317c73391",["Text"]="-----------------------------------\n-- Inspector's Gadget!\n--\n-- Kohlo-Lakolo, !pos -26.8 -6 190 240\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.INSPECTORS_GADGET)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.HEKO_OBI,\n    title    = xi.title.FAKE_MOUSTACHED_INVESTIGATOR,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.KNOW_ONES_ONIONS)\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kohlo-Lakolo'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getMainLvl() >= 5 and\n                        player:getFameLevel(xi.fameArea.WINDURST) >= 2 and\n                        not quest:getMustZone(player)\n                    then\n                        return quest:progressEvent(413) -- Quest starting event.\n                    else\n                        return quest:event(401) -- Default text.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [413] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepeted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kohlo-Lakolo'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.FAKE_MOUSTACHE) then\n                        return quest:progressEvent(421)\n                    else\n                        return quest:event(414)\n                    end\n                end,\n            },\n\n            -- Reminder text.\n            ['Gomada-Vulmada'] = quest:event(417),\n            ['Papo-Hopo']      = quest:event(416),\n            ['Pichichi']       = quest:event(415, 0, xi.keyItem.FAKE_MOUSTACHE),\n            ['Pyo_Nzon']       = quest:event(418),\n            ['Shanruru']       = quest:event(420),\n            ['Yafa_Yaa']       = quest:event(419, 0, xi.item.LINKSHELL),\n\n            onEventFinish =\n            {\n                [415] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [421] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setLocalVar('[2][42]mustZone', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Chamama'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.FAKE_MOUSTACHE) then\n                        return quest:event(553)\n                    else\n                        if quest:getVar(player, 'Prog') > 0 then\n                            return quest:progressEvent(551, 0, xi.keyItem.FAKE_MOUSTACHE)\n                        end\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        npcUtil.tradeHasExactly(trade, { { xi.item.BALL_OF_SARUTA_COTTON, 4 } }) and\n                        not player:hasKeyItem(xi.keyItem.FAKE_MOUSTACHE)\n                    then\n                        return quest:progressEvent(552)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [551] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n\n                [552] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.FAKE_MOUSTACHE)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.ONION_RINGS) == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            -- New default texts.\n            ['Gomada-Vulmada'] = quest:event(425):replaceDefault(),\n            ['Papo-Hopo']      = quest:event(424):replaceDefault(),\n            ['Pichichi']       = quest:event(423):replaceDefault(),\n            ['Pyo_Nzon']       = quest:event(426):replaceDefault(),\n            ['Shanruru']       = quest:event(428):replaceDefault(),\n            ['Yafa_Yaa']       = quest:event(427):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/SOB4_Onion_Rings.lua"]={["Path"]="scripts/quests/windurst/SOB4_Onion_Rings.lua",["SHA256"]="e1e4c2714b3a050cab7867023aa1dc291d6930012be01971be9852f897d62477",["Text"]="-----------------------------------\n-- Onion Rings\n--\n-- Kohlo-Lakolo, !pos -26.8 -6 190 240\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.ONION_RINGS)\n\nlocal function timedEvents(player, inTime, outATime)\n    local currentTime = VanadielTime()\n    local endTime     = quest:getVar(player, 'EndTime')\n\n    if currentTime < endTime then\n        return quest:event(inTime)\n    else\n        return quest:event(outATime)\n    end\nend\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.WINDURST,\n    title    = xi.title.STAR_ONION_BRIGADIER,\n}\n\nquest.sections =\n{\n    -- NOTE\n    -- From the moment you speak with Kohlo-Lakolo, if you dont have the Old Ring, a 24 hour time limit will start.\n    -- You still need to get the ring, no matter what.\n\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.INSPECTORS_GADGET)\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kohlo-Lakolo'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getMainLvl() >= 5 and\n                        player:getFameLevel(xi.fameArea.WINDURST) >= 3 and\n                        not quest:getMustZone(player)\n                    then\n                        if player:hasKeyItem(xi.keyItem.OLD_RING) then\n                            local currentTime = VanadielTime()\n                            local endTime     = quest:getVar(player, 'EndTime')\n\n                            if\n                                currentTime < endTime and\n                                quest:getVar(player, 'Prog') == 1\n                            then\n                                return quest:progressEvent(430, 0, xi.keyItem.OLD_RING) -- Quest starting event.\n                            else\n                                return quest:progressEvent(432, 0, xi.keyItem.OLD_RING) -- Instant Quest Complete.\n                            end\n                        else\n                            return quest:progressEvent(429) -- Timer start and reminder text.\n                        end\n                    else\n                        return quest:event(422) -- Default text.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [429] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                        quest:setVar(player, 'EndTime', VanadielTime() + xi.vanaTime.DAY) -- Set current quest started variables.\n                    end\n                end,\n\n                [430] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n\n                [432] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.OLD_RING)\n                        player:setLocalVar('[2][76]mustZone', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepeted. You didn't start with the \"Old Ring\" Key Item.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kohlo-Lakolo'] =\n            {\n                onTrigger = function(player, npc)\n                    return timedEvents(player, 431, 433)\n                end,\n            },\n\n            ['Gomada-Vulmada'] =\n            {\n                onTrigger = function(player, npc)\n                    return timedEvents(player, 435, 442)\n                end,\n            },\n\n            ['Papo-Hopo'] =\n            {\n                onTrigger = function(player, npc)\n                    return timedEvents(player, 434, 441)\n                end,\n            },\n\n            ['Pichichi'] =\n            {\n                onTrigger = function(player, npc)\n                    return timedEvents(player, 438, 445)\n                end,\n            },\n\n            ['Pyo_Nzon'] =\n            {\n                onTrigger = function(player, npc)\n                    return timedEvents(player, 436, 443)\n                end,\n            },\n\n            ['Shanruru'] =\n            {\n                onTrigger = function(player, npc)\n                    return timedEvents(player, 439, 446)\n                end,\n            },\n\n            ['Yafa_Yaa'] =\n            {\n                onTrigger = function(player, npc)\n                    return timedEvents(player, 437, 444)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [433] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.OLD_RING)\n                        player:setLocalVar('[2][76]mustZone', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['_6n2'] =\n            {\n                onTrigger = function(player, npc)\n                    local currentTime = VanadielTime()\n                    local endTime     = quest:getVar(player, 'EndTime')\n\n                    if currentTime < endTime then\n                        return quest:progressEvent(289)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [289] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.OLD_RING)\n                        player:setLocalVar('[2][76]mustZone', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CRYING_OVER_ONIONS) == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            -- New default texts.\n            ['Gomada-Vulmada'] = quest:event(442):replaceDefault(),\n            ['Papo-Hopo']      = quest:event(441):replaceDefault(),\n            ['Pichichi']       = quest:event(445):replaceDefault(),\n            ['Pyo_Nzon']       = quest:event(443):replaceDefault(),\n            ['Shanruru']       = quest:event(446):replaceDefault(),\n            ['Yafa_Yaa']       = quest:event(444):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/SOB5_Crying_Over_Onions.lua"]={["Path"]="scripts/quests/windurst/SOB5_Crying_Over_Onions.lua",["SHA256"]="3f1a0af62bc56876e1df79cd18b45085154b91f9c571b37fcc3f7e67b914524a",["Text"]="-----------------------------------\n-- Crying Over Onions\n--\n-- Kohlo-Lakolo, !pos -26.8 -6 190 240\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.CRYING_OVER_ONIONS)\n\nquest.reward =\n{\n    fame     = 50,\n    fameArea = xi.fameArea.WINDURST,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.ONION_RINGS)\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kohlo-Lakolo'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Reward') == 1 then\n                        if\n                            player:getMainLvl() >= 5 and\n                            player:getFameLevel(xi.fameArea.WINDURST) >= 5 and\n                            not quest:getMustZone(player)\n                        then\n                            return quest:progressEvent(496) -- Quest starting event.\n                        else\n                            return quest:event(450)\n                        end\n                    else\n                        if not quest:getMustZone(player) then\n                            return quest:progressEvent(449) -- Get previous quest reward.\n                        else\n                            return quest:event(440)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [449] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.BOUNCER_CLUB) then\n                        quest:setVar(player, 'Reward', 1)\n                        quest:setMustZone(player)\n                    end\n                end,\n\n                [496] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepeted in time.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kohlo-Lakolo'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(497)\n                    elseif quest:getVar(player, 'Prog') == 4 then\n                        return quest:event(512) -- Reminder text.\n                    else\n                        return quest:event(498) -- Reminder text.\n                    end\n                end,\n            },\n\n            ['Gomada-Vulmada'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:event(500)\n                    end\n                end,\n            },\n\n            ['Papo-Hopo'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:event(501)\n                    end\n                end,\n            },\n\n            ['Pichichi'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:event(503)\n                    end\n                end,\n            },\n\n            ['Pyo_Nzon'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:event(502)\n                    end\n                end,\n            },\n\n            ['Shanruru'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:event(504)\n                    end\n                end,\n            },\n\n            ['Yafa_Yaa'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:event(499)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [497] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Honoi-Gomoi'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(774, 0, xi.item.STAR_SPINEL)\n                    elseif quest:getVar(player, 'Prog') == 1 or quest:getVar(player, 'Prog') == 2 then\n                        return quest:event(777) -- Reminder text before trade.\n                    elseif quest:getVar(player, 'Prog') == 3 then\n                        return quest:event(778) -- Reminder text after trade\n                    elseif quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(776) -- Quest Complete.\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        (quest:getVar(player, 'Prog') == 1 or quest:getVar(player, 'Prog') == 2) and\n                        npcUtil.tradeHasExactly(trade, xi.item.STAR_SPINEL)\n                    then\n                        return quest:progressEvent(775, 0, xi.item.STAR_SPINEL)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [774] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [775] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.STAR_NECKLACE) then\n                        player:confirmTrade()\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n\n                [776] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setLocalVar('[2][77]mustZone', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Nanaa_Mihgo'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(598) -- Optional, one time only, dialog.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [598] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_PROMISE) == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            -- New default texts.\n            ['Gomada-Vulmada'] = quest:event(507):replaceDefault(),\n            ['Papo-Hopo']      = quest:event(508):replaceDefault(),\n            ['Pichichi']       = quest:event(511):replaceDefault(),\n            ['Pyo_Nzon']       = quest:event(510):replaceDefault(),\n            ['Shanruru']       = quest:event(504):replaceDefault(),\n            ['Yafa_Yaa']       = quest:event(506):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/SOB6_Wild_Card.lua"]={["Path"]="scripts/quests/windurst/SOB6_Wild_Card.lua",["SHA256"]="5d3dd93fbc929520a5fae3aa81a959c0f937fd89009db450176904d020d3b226",["Text"]="-----------------------------------\n-- Wild Card\n-- Log ID: 2, Quest ID: 77\n-- Honoi-Gumoi: !pos -195 -11 -120 238\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.WILD_CARD)\n\nquest.reward =\n{\n    fame     = 60,\n    fameArea = xi.fameArea.WINDURST,\n    title    = xi.title.DREAM_DWELLER,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CRYING_OVER_ONIONS)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Honoi-Gomoi'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getMainLvl() >= 5 and\n                        player:getFameLevel(xi.fameArea.WINDURST) >= 5 and\n                        not quest:getMustZone(player)\n                    then\n                        return quest:progressEvent(780) -- Quest starting event.\n                    else\n                        return quest:event(779) -- Default text.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [780] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepeted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kohlo-Lakolo'] = quest:progressEvent(545),\n            ['Papo-Hopo']    = quest:event(509),\n\n            onEventFinish =\n            {\n                [545] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.TORAIMARAI_CANAL] =\n        {\n            ['Treasure_Coffer'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    if\n                        not player:hasKeyItem(xi.keyItem.JOKER_CARD) and\n                        (questProgress == 2 or questProgress == 3)\n                    then\n                        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.JOKER_CARD)\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['_6n2'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then -- First meeting at house of hero.\n                        if player:getRank(xi.nation.WINDURST) < 9 then\n                            return quest:progressEvent(386) -- Meet Joker.\n                        else\n                            return quest:progressEvent(388) -- Meet Apururu.\n                        end\n                    elseif player:hasKeyItem(xi.keyItem.JOKER_CARD) then -- Second meeting at house of hero.\n                        if player:getRank(xi.nation.WINDURST) < 9 then\n                            return quest:progressEvent(387, 0, xi.keyItem.JOKER_CARD) -- Meet Joker after meeting Joker first.\n                        else\n                            return quest:progressEvent(389) -- Meet Apururu after meeting Joker first.\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [386] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2) -- 2 = Met Joker. Sets 2nd CS in Windurst Walls with either Joker or Apururu.\n                end,\n\n                [387] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.JOKER_CARD)\n                    npcUtil.giveCurrency(player, 'gil', 8000)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [388] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3) -- 3 = Met Apururu. Sets 2nd CS in Windurst Woods with Apururu.\n                end,\n\n                [389] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.JOKER_CARD)\n                    npcUtil.giveCurrency(player, 'gil', 8000)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Honoi-Gomoi'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(782) -- Quest Complete.\n                    else\n                        return quest:event(781) -- Reminder text.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [782] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setLocalVar('[2][78]mustZone', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Apururu'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(600) -- 2nd meeting with Apururu after meeting him in Hero's hause.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [600] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.JOKER_CARD)\n                    npcUtil.giveCurrency(player, 'gil', 8000)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Honoi-Gomoi'] = quest:event(783):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/SOB7_The_Promise.lua"]={["Path"]="scripts/quests/windurst/SOB7_The_Promise.lua",["SHA256"]="dd9aac3d3584f05f20109c02a013c13c86f8eac1165fa0bdb03b9c69ea7a6678",["Text"]="-----------------------------------\n-- The Promise\n--\n-- Kohlo-Lakolo, !pos -26.8 -6 190 240\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.THE_PROMISE)\n\nlocal function timedEvents(player, inTime, outATime)\n    if\n        quest:getVar(player, 'Prog') == 1 and\n        player:getRank(xi.nation.WINDURST) < 9\n    then\n        return quest:event(inTime)\n    else\n        return quest:event(outATime)\n    end\nend\n\nlocal function finalEvents(player, inTime, outATime)\n    if player:getCharVar('SOBfinalEvent') == 1 then\n        return quest:event(inTime)\n    else\n        return quest:event(outATime)\n    end\nend\n\nquest.reward =\n{\n    fame     = 60,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.PROMISE_BADGE,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.WILD_CARD)\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kohlo-Lakolo'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getMainLvl() >= 5 and\n                        player:getFameLevel(xi.fameArea.WINDURST) >= 5 and\n                        not quest:getMustZone(player)\n                    then\n                        if player:getRank(xi.nation.WINDURST) < 9 then\n                            return quest:progressEvent(513, 0, xi.keyItem.INVISIBLE_MAN_STICKER) -- Quest starting event in time.\n                        else\n                            return quest:progressEvent(532, 0, xi.keyItem.INVISIBLE_MAN_STICKER) -- Quest starting event late.\n                        end\n                    else\n                        if player:getRank(xi.nation.WINDURST) < 9 then\n                            return quest:event(505) -- Default text in time.\n                        else\n                            return quest:event(535) -- Default text late.\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [513] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 1) -- Start in time.\n                end,\n\n                [532] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepeted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Kohlo-Lakolo'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.INVISIBLE_MAN_STICKER) then\n                        if quest:getVar(player, 'Prog') == 1 then\n                            if player:getRank(xi.nation.WINDURST) < 9 then\n                                return quest:progressEvent(522, 0, xi.keyItem.INVISIBLE_MAN_STICKER) -- Quest Complete. In time.\n                            else\n                                return quest:progressEvent(542, 0, xi.keyItem.INVISIBLE_MAN_STICKER) -- Quest Complete. Started in time, arrived late.\n                            end\n                        else\n                            return quest:progressEvent(534, 0, xi.keyItem.INVISIBLE_MAN_STICKER) -- Quest Complete. Started late.\n                        end\n                    else\n                        if quest:getVar(player, 'Prog') == 1 then\n                            if player:getRank(xi.nation.WINDURST) < 9 then\n                                return quest:event(514) -- Reminder. In time.\n                            else\n                                return quest:event(543, 0, xi.keyItem.INVISIBLE_MAN_STICKER) -- Reminder. Started in time, but are late.\n                            end\n                        else\n                            return quest:event(533, 0, xi.keyItem.INVISIBLE_MAN_STICKER) -- Reminder. Started late.\n                        end\n                    end\n                end,\n            },\n\n            ['Gomada-Vulmada'] =\n            {\n                onTrigger = function(player, npc)\n                    return timedEvents(player, 518, 528)\n                end,\n            },\n\n            ['Papo-Hopo'] =\n            {\n                onTrigger = function(player, npc)\n                    return timedEvents(player, 515, 525)\n                end,\n            },\n\n            ['Pichichi'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 1 or\n                        player:getRank(xi.nation.WINDURST) >= 9\n                    then\n                        return quest:event(530)\n                    end\n                end,\n            },\n\n            ['Pyo_Nzon'] =\n            {\n                onTrigger = function(player, npc)\n                    return timedEvents(player, 517, 527)\n                end,\n            },\n\n            ['Shanruru'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 0 or\n                        player:getRank(xi.nation.WINDURST) >= 9\n                    then\n                        return quest:event(529)\n                    end\n                end,\n            },\n\n            ['Yafa_Yaa'] =\n            {\n                onTrigger = function(player, npc)\n                    return timedEvents(player, 516, 526)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [522] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.INVISIBLE_MAN_STICKER)\n                        player:setCharVar('SOBfinalEvent', 1)\n                    end\n                end,\n\n                [534] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.INVISIBLE_MAN_STICKER)\n                        player:setCharVar('SOBfinalEvent', 1)\n                    end\n                end,\n\n                [542] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.INVISIBLE_MAN_STICKER)\n                        player:setCharVar('SOBfinalEvent', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Chamama'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.INVISIBLE_MAN_STICKER) then\n                        return quest:event(800)\n                    elseif quest:getVar(player, 'Chamama') > 0 then\n                        return quest:event(798, 0, xi.item.SHOALWEED, xi.keyItem.INVISIBLE_MAN_STICKER)\n                    else\n                        return quest:progressEvent(797, 0, xi.item.SHOALWEED, xi.keyItem.INVISIBLE_MAN_STICKER)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Chamama') == 1 and\n                        npcUtil.tradeHasExactly(trade, xi.item.SHOALWEED) and\n                        not player:hasKeyItem(xi.keyItem.INVISIBLE_MAN_STICKER)\n                    then\n                        return quest:progressEvent(799, 0, 0, xi.keyItem.INVISIBLE_MAN_STICKER)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [797] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Chamama', 1)\n                end,\n\n                [799] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.INVISIBLE_MAN_STICKER)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Gomada-Vulmada'] =\n            {\n                onTrigger = function(player, npc)\n                    return finalEvents(player, 540, 590)\n                end,\n            },\n\n            ['Kohlo-Lakolo'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCharVar('SOBfinalEvent') == 1 then\n                        if player:hasKeyItem(xi.keyItem.DARK_MANA_ORB) then\n                            return quest:progressEvent(584)\n                        else\n                            return quest:event(528)\n                        end\n                    else\n                        local random = math.randomInt(0, 1)\n                        if random == 0 then\n                            return quest:event(544)\n                        else\n                            return quest:event(585)\n                        end\n                    end\n                end,\n            },\n\n            ['Papo-Hopo'] =\n            {\n                onTrigger = function(player, npc)\n                    return finalEvents(player, 537, 587)\n                end,\n            },\n\n            ['Pichichi'] =\n            {\n                onTrigger = function(player, npc)\n                    return finalEvents(player, 536, 586)\n                end,\n            },\n\n            ['Pyo_Nzon'] =\n            {\n                onTrigger = function(player, npc)\n                    return finalEvents(player, 539, 589)\n                end,\n            },\n\n            ['Shanruru'] =\n            {\n                onTrigger = function(player, npc)\n                    return finalEvents(player, 541, 591)\n                end,\n            },\n\n            ['Yafa_Yaa'] =\n            {\n                onTrigger = function(player, npc)\n                    return finalEvents(player, 538, 588)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [584] = function(player, csid, option, npc)\n                    player:setCharVar('SOBfinalEvent', 0)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Say_It_With_Flowers.lua"]={["Path"]="scripts/quests/windurst/Say_It_With_Flowers.lua",["SHA256"]="2f8cef14cfc0b0ce6f70799ccb7c832eab7cdd6ee4f6b497318160d7cb5effab",["Text"]="-----------------------------------\n-- Say it with Flowers\n-----------------------------------\n-- Log ID: 2, Quest ID: 50\n-- Moari-Kaaori !pos -252 -5 -230\n-----------------------------------\nlocal tahrongiID = zones[xi.zone.TAHRONGI_CANYON]\nlocal watersID   = zones[xi.zone.WINDURST_WATERS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.SAY_IT_WITH_FLOWERS)\n\nquest.reward =\n{\n    title = xi.title.CUPIDS_FLORIST,\n}\n\nlocal flowerList =\n{\n    [0] = { itemId = xi.item.CARNATION,  gil = 300 },\n    [1] = { itemId = xi.item.RED_ROSE,   gil = 200 },\n    [2] = { itemId = xi.item.RAIN_LILY,  gil = 250 },\n    [3] = { itemId = xi.item.LILAC,      gil = 150 },\n    [4] = { itemId = xi.item.AMARYLLIS,  gil = 200 },\n    [5] = { itemId = xi.item.MARGUERITE, gil = 100 },\n}\n\nlocal flowers =\n{\n    xi.item.CARNATION,\n    xi.item.RED_ROSE,\n    xi.item.RAIN_LILY,\n    xi.item.LILAC,\n    xi.item.AMARYLLIS,\n    xi.item.MARGUERITE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 2\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Moari-Kaaori'] = quest:progressEvent(514),\n\n            onEventFinish =\n            {\n                [514] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:setCharVar('SIWFSword', 1) -- Used to mark that the player has NOT recieved the sword reward yet.\n                        quest:begin(player)\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return vars.Prog == 1\n        end,\n\n        [xi.zone.TAHRONGI_CANYON] =\n        {\n            ['Tahrongi_Cacti'] =\n            {\n                onTrigger = function(player, npc)\n                    if npcUtil.giveItem(player, xi.item.TAHRONGI_CACTUS, { silent = true }) then -- The player can obtain as many as they want. They are unsellable.\n                        return quest:messageSpecial(tahrongiID.text.BUD_BREAKS_OFF, 0, xi.item.TAHRONGI_CACTUS) -- This dialogue does not currently play on retail\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Kenapa-Keppa'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 1 then\n                        return quest:event(519)\n                    end\n                end,\n            },\n\n            ['Ohbiru-Dohbiru'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 1 then\n                        return quest:event(517)\n                    elseif quest:getMustZone(player) then\n                        return quest:progressEvent(518)\n                    else\n                        return quest:event(516, { [4] = xi.item.TAHRONGI_CACTUS })\n                    end\n                end,\n            },\n\n            ['Moari-Kaaori'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(515)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.TAHRONGI_CACTUS) then\n                        if player:getCharVar('SIWFSword') == 1 then\n                            return quest:progressEvent(520) -- Player has not received the sword already\n                        else\n                            return quest:progressEvent(525, 400) -- Player has received the sword already\n                        end\n                    elseif npcUtil.tradeSetInList(trade, flowers) then\n                        return quest:progressEvent(522) -- Player traded a flower that isn't the cactus.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [516] = function(player, csid, option, npc)\n                    if option < 7 then\n                        local choice = flowerList[option]\n                        if\n                            choice and\n                            player:getGil() >= choice.gil\n                        then\n                            if npcUtil.giveItem(player, choice.itemId) then\n                                player:delGil(choice.gil)\n                                quest:setMustZone(player)\n                            end\n                        else\n                            player:messageText(npc, watersID.text.WHAT_DO_YOU_MEAN)\n                        end\n                    elseif option == 7 then\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n\n                [520] = function(player, csid, option, npc) -- Cactus trade with Iron Sword reward\n                    if npcUtil.giveItem(player, xi.item.IRON_SWORD) then\n                        quest:complete(player)\n                        player:confirmTrade()\n                        player:addFame(xi.fameArea.WINDURST, 10)\n                        quest:setMustZone(player)\n                        quest:setVar(player, 'Stage', 1)\n                        player:setCharVar('SIWFSword', 0) -- Removes the var so the player cannot obtain the sword again.\n                    end\n                end,\n\n                [522] = function(player, csid, option, npc) -- Flower trade\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:addFame(xi.fameArea.WINDURST, 10)\n                        player:addGil(100)\n                        quest:setMustZone(player)\n                    end\n                end,\n\n                [525] = function(player, csid, option, npc) -- Cactus trade repeat\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:addFame(xi.fameArea.WINDURST, 10)\n                        player:addGil(400) -- Obtained gil text baked into the cs\n                        quest:setMustZone(player)\n                        quest:setVar(player, 'Stage', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n            vars.Prog == 0\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Moari-Kaaori'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(521)\n                    elseif quest:getVar(player, 'Stage') == 1 then\n                        return quest:progressEvent(685, 0, xi.item.TAHRONGI_CACTUS) -- Player had turned in a cactus\n                    else\n                        return quest:progressEvent(523) -- Player had turned in a flower\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [523] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [685] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Scooped.lua"]={["Path"]="scripts/quests/windurst/Scooped.lua",["SHA256"]="67975067a41b6e169e725f54851ca6d152a99f84646718ea84b05c6bf98d01fb",["Text"]="-----------------------------------\n-- Scooped!\n-----------------------------------\n-- !addquest 2 38\n-- Hariga-Origa : !pos -70.244, -3.800, -4.439\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.SCOOPED)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    gil      = 1500,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_HEADLINES)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Naiko-Paneiko'] = quest:progressEvent(676),\n\n            onEventFinish =\n            {\n                [676] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Naiko-Paneiko'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.BRONZE_BOX) then\n                        return quest:progressEvent(680)\n                    end\n                end,\n\n                onTrigger = quest:event(677),\n            },\n\n            ['Chyuk-Kochak'] = quest:event(679),\n\n            onEventFinish =\n            {\n                [680] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Chyuk-Kochak'] = quest:event(682):replaceDefault(),\n\n            ['Naiko-Paneiko'] = quest:event(663):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Star_Struck.lua"]={["Path"]="scripts/quests/windurst/Star_Struck.lua",["SHA256"]="019f001c5b88d6ee05f4cf0a938c8be13575709f8b5fcb15b60fc5cc33eef856",["Text"]="-----------------------------------\n-- Star Struck\n-----------------------------------\n-- Log ID: 2, Quest ID: 10\n-- Koru-Moru : !pos -120 -6 124 239\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.STAR_STRUCK)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.COMPOUND_EYE_CIRCLET,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Koru-Moru'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasItem(xi.item.TORN_EPISTLE) then\n                        return quest:progressEvent(197)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [197] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Koru-Moru'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.TORN_EPISTLE) then\n                        return quest:progressEvent(199)\n                    elseif npcUtil.tradeHasExactly(trade, xi.item.METEORITE) then\n                        return quest:progressEvent(211)\n                    end\n                end,\n\n                onTrigger = quest:event(198),\n            },\n\n            ['Luuh_Koplehn'] = quest:event(200),\n\n            onEventFinish =\n            {\n                [199] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveCurrency(player, 'gil', 50)\n                end,\n\n                [211] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n\n                        xi.quest.setMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.BLAST_FROM_THE_PAST)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_PUPPET_MASTER)\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Koru-Moru'] = quest:event(213):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/THF_AF1_The_Tenshodo_Showdown.lua"]={["Path"]="scripts/quests/windurst/THF_AF1_The_Tenshodo_Showdown.lua",["SHA256"]="42ddf0cd41d3717b3cb9f340203165f51d53e1783bde6844ce56cd2e370b340c",["Text"]="-----------------------------------\n-- The Tenshodo Showdown\n-----------------------------------\n-- Log ID: 2, Quest ID: 69\n-- !addquest 2 69\n-- Nanaa Mihgo : !pos 62 -4 240 241\n-- Harnek      : !pos 44 0 -19 245\n-- Elfriede    : !pos 61 -15 10 248\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.THE_TENSHODO_SHOWDOWN)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.WINDURST,\n    item = xi.item.MARAUDERS_KNIFE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainJob() == xi.job.THF and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Nanaa_Mihgo'] = quest:progressEvent(496),\n\n            onEventFinish =\n            {\n                [496] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_THE_TENSHODO)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Harnek'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.LETTER_FROM_THE_TENSHODO) then\n                        return quest:progressEvent(10021, 0, xi.keyItem.LETTER_FROM_THE_TENSHODO, xi.keyItem.TENSHODO_ENVELOPE)\n                    elseif player:hasKeyItem(xi.keyItem.SIGNED_ENVELOPE) then\n                        return quest:progressEvent(10022)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10021] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.LETTER_FROM_THE_TENSHODO)\n                    npcUtil.giveKeyItem(player, xi.keyItem.TENSHODO_ENVELOPE)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [10022] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.SIGNED_ENVELOPE)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Elfriede'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.BOWL_OF_QUADAV_STEW) and\n                        quest:getVar(player, 'Prog') == 2\n                    then\n                        return quest:progressEvent(10004, 0, xi.keyItem.TENSHODO_ENVELOPE, xi.item.BOWL_OF_QUADAV_STEW)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:progressEvent(10002, 0, xi.keyItem.TENSHODO_ENVELOPE, xi.item.BOWL_OF_QUADAV_STEW)\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(10003, 0, 0, xi.item.BOWL_OF_QUADAV_STEW)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10002] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [10004] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:delKeyItem(xi.keyItem.TENSHODO_ENVELOPE)\n                    npcUtil.giveKeyItem(player, xi.keyItem.SIGNED_ENVELOPE)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Nanaa_Mihgo'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(497)\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(498)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.AS_THICK_AS_THIEVES) == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainJob() == xi.job.THF and\n                player:getMainLvl() < xi.settings.main.AF2_QUEST_LEVEL\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Nanaa_Mihgo'] = quest:event(503):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/THF_AF2_As_Thick_as_Thieves.lua"]={["Path"]="scripts/quests/windurst/THF_AF2_As_Thick_as_Thieves.lua",["SHA256"]="b1e934f9f292f1858934f8b82b9f708998c2af8345e8e32893dbe6a224a7b34d",["Text"]="-----------------------------------\n-- As Thick as Thieves\n-----------------------------------\n-- !addquest 2 70\n-- Nanaa Mihgo    : !pos 62 -4 240 241\n-- qm2 (Tower)    : !pos 196.830 31.300 206.078 120\n-- qm3 (Tower)    : !pos 417.121 15.598 -137.466 120\n-- qm4 (Tower)    : !pos 129.587 -0.600 -235.525 120\n-- qm5 (Tower)    : !pos -117.713 15.237 45.929 120\n-- qm6 (Tower)    : !pos 363.481 23.600 6.335 120\n-- qm7 (Tower)    : !pos -193.869 15.400 276.837 120\n-- Sniggnix       : !pos -45.832 4.498 -135.029 245\n-- qm3 (Saltvix)  : !pos -367.367 2.999 229.020 191\n-- qm4 (Grasswix) : !pos -375.379 -2.221 445.034 191\n-- qm5 (Eggblix)  : !pos -462.436 2.456 -141.171 191\n-- qm2 (???)      : !pos -232.924 99.107 442.990 106\n-----------------------------------\nlocal dangrufID        = zones[xi.zone.DANGRUF_WADI]\nlocal northGustabergID = zones[xi.zone.NORTH_GUSTABERG]\nlocal sauromugueID     = zones[xi.zone.SAUROMUGUE_CHAMPAIGN]\n-----------------------------------\n\n-- 5 yalms out from the tower wall each ??? sits on\nlocal climbpixSpawn =\n{\n    ['qm2'] = {  191.4, 31.3, 209.0  },\n    ['qm3'] = {  410.0, 16.5, -134.0 },\n    ['qm4'] = {  124.7, -0.6, -234.4 },\n    ['qm5'] = { -119.5, 15.2, 50.6   },\n    ['qm6'] = {  366.0, 23.5, 12.5   },\n    ['qm7'] = { -190.0, 16.0, 270.6  },\n}\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.AS_THICK_AS_THIEVES)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.ROGUES_BONNET,\n}\n\nlocal function isNaked(player)\n    for i = xi.slot.MAIN, xi.slot.BACK do\n        if player:getEquipID(i) ~= 0 then\n            return false\n        end\n    end\n\n    return true\nend\n\nlocal towerIncorrectTrade = function(player, npc, trade)\n    if npcUtil.tradeHasExactly(trade, xi.item.GRAPNEL) then\n        return quest:messageSpecial(sauromugueID.text.THF_AF_WALL_OFFSET + 3, 0, xi.item.GRAPNEL)\n    end\nend\n\nlocal towerOnTrigger = function(player, npc)\n    if not player:hasKeyItem(xi.keyItem.FIRST_SIGNED_FORGED_ENVELOPE) then\n        local climbpix = GetMobByID(sauromugueID.mob.CLIMBPIX_HIGHRISE)\n        if\n            climbpix and\n            not climbpix:isSpawned()\n        then\n            local spawnPos = climbpixSpawn[npc:getName()]\n            climbpix:setSpawn(spawnPos[1], spawnPos[2], spawnPos[3])\n        end\n\n        if\n            quest:getLocalVar(npc, 'Option') == 1 and\n            not player:findItem(xi.item.GRAPNEL) and\n            npcUtil.popFromQM(player, npc, sauromugueID.mob.CLIMBPIX_HIGHRISE, { hide = 0, look = true })\n        then\n            return quest:messageSpecial(sauromugueID.text.THF_AF_MOB)\n        else\n            -- It is impossible to climb this wall with your bare hands.\n            return quest:messageSpecial(sauromugueID.text.THF_AF_WALL_OFFSET)\n        end\n    else\n        -- There is no longer any need to climb the tower.\n        return quest:messageSpecial(sauromugueID.text.THF_AF_WALL_OFFSET + 1)\n    end\nend\n\nlocal function handleDangrufMinigame(player, winEventId, loseEventId, itemPlaced)\n    local rand1 = math.randomInt(1, 999)\n    local rand2 = math.randomInt(1, 999)\n\n    if rand1 > rand2 then\n        player:messageSpecial(dangrufID.text.YOU_PLACE_ITEM, 0, itemPlaced)\n        return quest:progressEvent(winEventId, xi.item.REGAL_DIE, 0, rand1, rand2)\n    else\n        player:messageSpecial(dangrufID.text.YOU_PLACE_ITEM, 0, itemPlaced)\n        return quest:progressEvent(loseEventId, 0, 0, rand1, rand2)\n    end\nend\n\nlocal lostMinigameEvent = function(player, csid, option, npc)\n    player:confirmTrade()\n\n    -- Only Saltvix has an alternate CS progression on repeating attempts\n    if csid == 139 or csid == 145 then\n        quest:setVar(player, 'failedGame', 1)\n    end\n\n    if option == 1 then\n        player:messageSpecial(dangrufID.text.GOBLIN_BEAT_YOU)\n    elseif option == 2 then\n        player:messageSpecial(dangrufID.text.YOU_GAVE_UP)\n    end\nend\n\nlocal wonMinigameEvent = function(player, csid, option, npc)\n    player:confirmTrade()\n\n    if option == 0 then\n        if csid == 136 or csid == 142 then\n            quest:setVar(player, 'failedGame', 0)\n        end\n\n        player:messageSpecial(dangrufID.text.YOU_BEAT_GOBLIN)\n        quest:setVar(player, 'Prog', quest:getVar(player, 'Prog') + 1)\n    elseif option == 2 then\n        if csid == 136 or csid == 142 then\n            quest:setVar(player, 'failedGame', 1)\n        end\n\n        player:messageSpecial(dangrufID.text.YOU_GAVE_UP)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_TENSHODO_SHOWDOWN) and\n                player:getMainJob() == xi.job.THF and\n                player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Nanaa_Mihgo'] = quest:progressEvent(504, 0, xi.keyItem.SIGNED_ENVELOPE, xi.keyItem.TENSHODO_ENVELOPE),\n\n            onEventFinish =\n            {\n                [504] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, { xi.keyItem.GANG_WHEREABOUTS_NOTE, xi.keyItem.FIRST_FORGED_ENVELOPE, xi.keyItem.SECOND_FORGED_ENVELOPE })\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.DANGRUF_WADI] =\n        {\n            ['qm3'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.CHUNK_OF_ROCK_SALT) then\n                        local questProgress = quest:getVar(player, 'Prog')\n                        local eventOffset   = quest:getVar(player, 'failedGame') == 0 and 136 or 142\n\n                        if questProgress == 1 then\n                            return handleDangrufMinigame(player, eventOffset, eventOffset + 3, xi.item.CHUNK_OF_ROCK_SALT)\n                        elseif questProgress > 1 then\n                            player:messageSpecial(dangrufID.text.BEAT_SALTVIX)\n                        end\n                    end\n                end,\n            },\n\n            ['qm4'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.CLUMP_OF_GAUSEBIT_WILDGRASS) then\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if questProgress == 2 then\n                            return handleDangrufMinigame(player, 137, 140, xi.item.CLUMP_OF_GAUSEBIT_WILDGRASS)\n                        elseif questProgress < 2 then\n                            return quest:messageSpecial(dangrufID.text.DONT_WASTE_TIME)\n                        elseif questProgress > 2 then\n                            return quest:messageSpecial(dangrufID.text.BEAT_GRASSWIX)\n                        end\n                    end\n                end,\n            },\n\n            ['qm5'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.LIZARD_EGG) then\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if questProgress == 3 then\n                            return handleDangrufMinigame(player, 138, 141, xi.item.LIZARD_EGG)\n                        elseif questProgress < 3 then\n                            return quest:messageSpecial(dangrufID.text.JUST_WONT_DO)\n                        elseif questProgress > 3 then\n                            return quest:messageSpecial(dangrufID.text.BEAT_EGGBLIX)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [136] = wonMinigameEvent,\n                [137] = wonMinigameEvent,\n                [138] = wonMinigameEvent,\n                [139] = lostMinigameEvent,\n                [140] = lostMinigameEvent,\n                [141] = lostMinigameEvent,\n                [142] = wonMinigameEvent,\n                [145] = lostMinigameEvent,\n            },\n        },\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Sniggnix'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.REGAL_DIE) and\n                        quest:getVar(player, 'Prog') == 6\n                    then\n                        return quest:progressEvent(10026, 0, xi.item.REGAL_DIE, math.randomInt(1, 700))\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    -- NOTE: 'Prog' questVar is only used for the gambling phase of this quest.  All other tracking utilizes\n                    -- key items obtained.\n                    local questProgress = quest:getVar(player, 'Prog')\n                    local rand1 = math.randomInt(1, 999)\n                    local rand2 = math.randomInt(1, 999)\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(10024, 0, xi.item.REGAL_DIE, rand1, rand2)\n                    elseif\n                        questProgress >= 1 and\n                        questProgress <= 5\n                    then\n                        return quest:progressEvent(10025, 0, xi.item.REGAL_DIE, rand1, rand2)\n                    else\n                        return quest:progressEvent(10023)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10024] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [10026] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:delKeyItem(xi.keyItem.SECOND_FORGED_ENVELOPE)\n                    npcUtil.giveKeyItem(player, xi.keyItem.SECOND_SIGNED_FORGED_ENVELOPE)\n                    quest:setVar(player, 'Prog', 7)\n                end,\n            },\n        },\n\n        [xi.zone.NORTH_GUSTABERG] =\n        {\n            ['Gambilox_Wanderling'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        quest:setVar(player, 'Prog', 5)\n                    end\n                end,\n            },\n\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 4 then\n                        npcUtil.popFromQM(player, npc, northGustabergID.mob.GAMBILOX_WANDERLING, { hide = 0 })\n                        return quest:messageSpecial(northGustabergID.text.SENSE_EVIL_PRESENCE)\n                    elseif questProgress == 5 then\n                        return quest:progressEvent(200, xi.item.REGAL_DIE)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [200] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.REGAL_DIE) then\n                        quest:setVar(player, 'Prog', 6)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SAUROMUGUE_CHAMPAIGN] =\n        {\n            ['qm2'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        not player:hasKeyItem(xi.keyItem.FIRST_SIGNED_FORGED_ENVELOPE) and\n                        npcUtil.tradeHasExactly(trade, xi.item.GRAPNEL)\n                    then\n                        if isNaked(player) then\n                            return quest:progressEvent(2, 0, xi.item.GRAPNEL)\n                        else\n                            player:messageSpecial(sauromugueID.text.THF_AF_WALL_OFFSET + 2, 0, xi.item.GRAPNEL)\n                        end\n                    end\n                end,\n\n                onTrigger = towerOnTrigger,\n            },\n\n            ['qm3'] =\n            {\n                onTrade   = towerIncorrectTrade,\n                onTrigger = towerOnTrigger,\n            },\n\n            ['qm4'] =\n            {\n                onTrade   = towerIncorrectTrade,\n                onTrigger = towerOnTrigger,\n            },\n\n            ['qm5'] =\n            {\n                onTrade   = towerIncorrectTrade,\n                onTrigger = towerOnTrigger,\n            },\n\n            ['qm6'] =\n            {\n                onTrade   = towerIncorrectTrade,\n                onTrigger = towerOnTrigger,\n            },\n\n            ['qm7'] =\n            {\n                onTrade   = towerIncorrectTrade,\n                onTrigger = towerOnTrigger,\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:delKeyItem(xi.keyItem.FIRST_FORGED_ENVELOPE)\n                    npcUtil.giveKeyItem(player, xi.keyItem.FIRST_SIGNED_FORGED_ENVELOPE)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Bopa_Greso']  = quest:progressEvent(506),\n            ['Cha_Lebagta'] = quest:progressEvent(507, 0, xi.item.GRAPNEL),\n\n            ['Nanaa_Mihgo'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.FIRST_SIGNED_FORGED_ENVELOPE) and\n                        player:hasKeyItem(xi.keyItem.SECOND_SIGNED_FORGED_ENVELOPE)\n                    then\n                        return quest:progressEvent(508)\n                    else\n                        return quest:progressEvent(505, 0, xi.keyItem.GANG_WHEREABOUTS_NOTE)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [508] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.GANG_WHEREABOUTS_NOTE)\n                        player:delKeyItem(xi.keyItem.FIRST_SIGNED_FORGED_ENVELOPE)\n                        player:delKeyItem(xi.keyItem.SECOND_SIGNED_FORGED_ENVELOPE)\n                        player:setLocalVar('Quest[2][71]mustZone', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/THF_AF3_Hitting_the_Marquisate.lua"]={["Path"]="scripts/quests/windurst/THF_AF3_Hitting_the_Marquisate.lua",["SHA256"]="9b2c64754a034a0d89add164f93a5d7374fc7ebae6734ac536c1e00de0181416",["Text"]="-----------------------------------\n-- Hitting the Marquisate\n-----------------------------------\n-- !addquest 2 71\n-- Nanaa Mihgo     : !pos 62 -4 240 241\n-- Yatniel         : !pos -66.817 -7 -126.594 245\n-- Hagain          : !pos 12.62 -16 81.4 249\n-- qm6 (???)       : !pos -220.039 -5.500 194.192 200\n-- qm5 (???)       : !pos -259.927 -5.500 194.410 200\n-- qm12 (???)      : !pos -245.603 -5.500 139.855 200\n-- qm13 (???)      : !pos -194.166 -5.500 139.969 200\n-- qm10 (???)      : !pos -139.895 -5.500 154.513 200\n-- qm9 (???)       : !pos -140.039 -5.500 285.999 200\n-- qm15 (???)      : !pos 19.893 -5.500 325.767 200\n-- qm2 (La Theine) : !pos -72.99 54.599 -443.126 102\n-- NOTE: Garlaige QM order is based on quest progression\n-----------------------------------\nlocal garlaigeID = zones[xi.zone.GARLAIGE_CITADEL]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.HITTING_THE_MARQUISATE)\n\nquest.reward =\n{\n    item  = xi.item.ROGUES_POULAINES,\n    title = xi.title.PARAGON_OF_THIEF_EXCELLENCE,\n}\n\n-- Data for reused functions for the initial six Garlaige QMs.  Ordered by quest\n-- flow.\n-- Table Format: Required Progress Value, Trigger Event, messageSpecial offset\nlocal garlaigeQmInfo =\n{\n    ['qm6']  = { 1, 50, 1 },\n    ['qm5']  = { 2, 51, 2 },\n    ['qm12'] = { 3, 52, 0 },\n    ['qm13'] = { 4, 53, 0 },\n    ['qm10'] = { 5, 54, 3 },\n    ['qm9']  = { 6, 55, 0 },\n}\n\nlocal garlaigeQmOnTrigger = function(player, npc)\n    local qmData = garlaigeQmInfo[npc:getName()]\n\n    if\n        player:hasKeyItem(xi.keyItem.BOMB_INCENSE) and\n        quest:getVar(player, 'hagainProg') == qmData[1]\n    then\n        player:messageSpecial(garlaigeID.text.PRESENCE_FROM_CEILING)\n        return quest:progressCutscene(qmData[2], xi.keyItem.BOMB_INCENSE)\n    end\nend\n\nlocal garlaigeQmOnEventFinish = function(player, csid, option, npc)\n    local qmData = garlaigeQmInfo[npc:getName()]\n\n    if option == 1 then\n        player:messageSpecial(garlaigeID.text.THE_PRESENCE_MOVES + qmData[3]) -- Presence moved west.\n        quest:incrementVar(player, 'hagainProg', 1)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                not quest:getMustZone(player) and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.AS_THICK_AS_THIEVES) and\n                player:getMainJob() == xi.job.THF and\n                player:getMainLvl() >= xi.settings.main.AF3_QUEST_LEVEL\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Nanaa_Mihgo'] = quest:progressEvent(512),\n\n            onEventFinish =\n            {\n                [512] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.CAT_BURGLARS_NOTE)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.GARLAIGE_CITADEL] =\n        {\n            ['qm5'] =\n            {\n                onTrigger = garlaigeQmOnTrigger,\n            },\n\n            ['qm6'] =\n            {\n                onTrigger = garlaigeQmOnTrigger,\n            },\n\n            ['qm9'] =\n            {\n                onTrigger = garlaigeQmOnTrigger,\n            },\n\n            ['qm10'] =\n            {\n                onTrigger = garlaigeQmOnTrigger,\n            },\n\n            ['qm12'] =\n            {\n                onTrigger = garlaigeQmOnTrigger,\n            },\n\n            ['qm13'] =\n            {\n                onTrigger = garlaigeQmOnTrigger,\n            },\n\n            ['qm15'] =\n            {\n                onTrigger = function(player, npc)\n                    local hagainProgress = quest:getVar(player, 'hagainProg')\n\n                    if hagainProgress == 7 then\n                        if\n                            GetSystemTime() <= GetNPCByID(garlaigeID.npc.CHANDELIER_QM):getLocalVar('chandelierCooldown')\n                        then\n                            return quest:messageSpecial(garlaigeID.text.THE_PRESENCE_MOVES + 7)\n                        elseif\n                            not GetMobByID(garlaigeID.mob.CHANDELIER):isSpawned() and\n                            player:hasKeyItem(xi.keyItem.BOMB_INCENSE)\n                        then\n                            player:messageSpecial(garlaigeID.text.HEAT_FROM_CEILING)\n                            return quest:progressCutscene(56, xi.keyItem.BOMB_INCENSE)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [50] = garlaigeQmOnEventFinish,\n                [51] = garlaigeQmOnEventFinish,\n                [52] = garlaigeQmOnEventFinish,\n                [53] = garlaigeQmOnEventFinish,\n                [54] = garlaigeQmOnEventFinish,\n                [55] = garlaigeQmOnEventFinish,\n\n                [56] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npc:timer(5000, function(npcArg)\n                            npcUtil.popFromQM(player, npc, garlaigeID.mob.CHANDELIER, { hide = 0, claim = false })\n                            player:messageSpecial(garlaigeID.text.THE_PRESENCE_MOVES + 5) -- Something flies out from the ceiling!\n                        end)\n                    else\n                        player:messageSpecial(garlaigeID.text.THE_PRESENCE_MOVES + 6) -- The presence in the ceiling still lingers...\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.LA_THEINE_PLATEAU] =\n        {\n            ['qm2'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.PICKAXE) and\n                        quest:getVar(player, 'nanaaProg') == 1\n                    then\n                        return quest:progressEvent(119, 0, xi.item.ROGUES_POULAINES, player:getNation(), xi.item.PICKAXE)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [119] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:delKeyItem(xi.keyItem.CAT_BURGLARS_NOTE)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Yatniel'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, { { xi.item.QUAKE_GRENADE, 4 } })\n                    then\n                        return quest:progressEvent(10031)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local yatnielProgress = quest:getVar(player, 'yatnielProg')\n\n                    if yatnielProgress == 0 then\n                        return quest:progressEvent(10029, 0, xi.item.QUAKE_GRENADE)\n                    elseif yatnielProgress == 1 then\n                        return quest:progressEvent(10030, 0, xi.item.QUAKE_GRENADE)\n                    elseif yatnielProgress == 2 then\n                        return quest:progressEvent(10032)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10029] = function(player, csid, option, npc)\n                    quest:setVar(player, 'yatnielProg', 1)\n                end,\n\n                [10031] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'yatnielProg', 2)\n                end,\n            },\n        },\n\n        [xi.zone.MHAURA] =\n        {\n            ['Hagain'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.LUMP_OF_CHANDELIER_COAL) then\n                        return quest:progressEvent(10005)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local hagainProgress = quest:getVar(player, 'hagainProg')\n\n                    if hagainProgress == 0 then\n                        return quest:progressEvent(10003, 0, xi.keyItem.BOMB_INCENSE, xi.item.LUMP_OF_CHANDELIER_COAL)\n                    elseif hagainProgress == 8 then\n                        return quest:progressEvent(10006)\n                    else\n                        return quest:progressEvent(10004, 0, xi.keyItem.BOMB_INCENSE, xi.item.LUMP_OF_CHANDELIER_COAL)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10003] = function(player, csid, option, npc)\n                    quest:setVar(player, 'hagainProg', 1)\n                    npcUtil.giveKeyItem(player, xi.keyItem.BOMB_INCENSE)\n                end,\n\n                [10005] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:delKeyItem(xi.keyItem.BOMB_INCENSE)\n                    quest:setVar(player, 'hagainProg', 8)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Nanaa_Mihgo'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'yatnielProg') == 2 and\n                        quest:getVar(player, 'hagainProg') == 8\n                    then\n                        return quest:progressEvent(516)\n                    elseif quest:getVar(player, 'nanaaProg') == 1 then\n                        return quest:progressEvent(517)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [516] = function(player, csid, option, npc)\n                    quest:setVar(player, 'nanaaProg', 1)\n                    quest:setVar(player, 'yatnielProg', 0)\n                    quest:setVar(player, 'hagainProg', 0)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Teachers_Pet.lua"]={["Path"]="scripts/quests/windurst/Teachers_Pet.lua",["SHA256"]="5f0a4d409263c5db76f9d935a3b7c169fad432392dcddc9acd9d8d5a11576805",["Text"]="-----------------------------------\n-- Teacher's Pet\n-----------------------------------\n-- Log ID: 2, Quest ID: 28\n-- Moreno-Toeno : !pos 169 -1.25 159 238\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.TEACHERS_PET)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.WINDURST,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Moreno-Toeno'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(437)\n                    else\n                        return quest:progressEvent(438, 0, xi.item.BIRD_FEATHER, xi.item.TWO_LEAF_MANDRAGORA_BUD)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [437] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [438] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Prog', 0)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Moreno-Toeno'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.BIRD_FEATHER, xi.item.TWO_LEAF_MANDRAGORA_BUD }) then\n                        return quest:progressEvent(440, 250, xi.item.BIRD_FEATHER, xi.item.TWO_LEAF_MANDRAGORA_BUD)\n                    end\n                end,\n\n                onTrigger = quest:event(439, 0, xi.item.BIRD_FEATHER, xi.item.TWO_LEAF_MANDRAGORA_BUD),\n            },\n\n            onEventFinish =\n            {\n                [440] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:addGil(250) -- \"Obtained X gil.\" Text is baked into the CS, so gil needs to be given outside of the quest rewards.\n\n                    if quest:complete(player) then\n                        xi.quest.setMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_THE_GRADE)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/The_Fanged_One.lua"]={["Path"]="scripts/quests/windurst/The_Fanged_One.lua",["SHA256"]="70dfd869cb5ecbf4fb6a522873c0d0c2c9143f4c75772991645908104d34591c",["Text"]="-----------------------------------\n-- The Fanged One\n-----------------------------------\n-- Log ID: 2, Quest ID: 31\n-- Perih Vashai: !pos 117 -3 92 241\n-- Tiger Bones: !pos 666 -8 -379 120\n-- Keeping Old Sabertooth and Tiger Bones in separate lua's due to special functions.\n-----------------------------------\nlocal windurstWoodsID = zones[xi.zone.WINDURST_WOODS]\nlocal sauromugueID    = zones[xi.zone.SAUROMUGUE_CHAMPAIGN]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.THE_FANGED_ONE)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.RANGERS_NECKLACE,\n    title    = xi.title.THE_FANGED_ONE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Perih_Vashai'] = quest:progressEvent(351),\n\n            onEventFinish =\n            {\n                [351] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Perih_Vashai'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:event(352)\n                    elseif player:hasKeyItem(xi.keyItem.OLD_TIGERS_FANG) then\n                        return quest:progressEvent(357)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.BLACK_TIGER_FANG) then\n                        return quest:event(356)\n                    end\n                end,\n            },\n\n            ['Kapeh_Myohrye'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(354)\n                end,\n            },\n\n            ['Muhk_Johldy'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(353)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [356] = function(player, csid, option, npc)\n                    player:tradeComplete() -- capture shows taking black tiger fang if traded.\n                end,\n\n                [357] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.OLD_TIGERS_FANG)\n                        player:unlockJob(xi.job.RNG)\n                        npcUtil.giveKeyItem(player, xi.keyItem.JOB_GESTURE_RANGER)\n                        player:messageSpecial(windurstWoodsID.text.PERIH_VASHAI_DIALOG)\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SAUROMUGUE_CHAMPAIGN] =\n        -- The logic for this specific mechanic is unique. Therefore, the mob logic and onMobDeath\n        -- resides in the Old_Sabertooth.lua onMobSpawn, onMobFight, and onMobDeath.\n        -- Currently, unable to have the onMobDeath function load from this file due to enmity.\n        -- Issue was raised to LSB for consideration on how to adjust moving forward.\n        {\n            ['Tiger_Bones'] =\n            {\n                onTrigger = function(player, npc)\n                    local oldTiger = GetMobByID(sauromugueID.mob.OLD_SABERTOOTH)\n\n                    if not oldTiger then\n                        return quest:noAction()\n                    end\n\n                    if\n                        quest:getVar(player, 'Timer') > GetSystemTime() and\n                        not player:hasKeyItem(xi.keyItem.OLD_TIGERS_FANG)\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.OLD_TIGERS_FANG)\n                        quest:setVar(player, 'Prog', 1)\n                        return quest:noAction()\n                    elseif\n                        quest:getVar(player, 'Prog') == 0 and\n                        quest:getVar(player, 'Wait') <= GetSystemTime() and\n                        not oldTiger:isSpawned()\n                    then\n                        SpawnMob(sauromugueID.mob.OLD_SABERTOOTH)\n                        return quest:messageSpecial(sauromugueID.text.OLD_SABERTOOTH_DIALOG_I)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Perih_Vashai'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(358)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/The_Moonlit_Path.lua"]={["Path"]="scripts/quests/windurst/The_Moonlit_Path.lua",["SHA256"]="f6b225d92944ffedcd94d49528665e64c251560194b3c84cdc0e005af9dbd934",["Text"]="-----------------------------------\n-- The Moonlit Path\n-----------------------------------\n-- Log ID: 2, Quest ID: 9\n-- !addquest 2 9\n-- Leepe-Hoppe : !pos 11.432 -9.749 -197.475 238\n-----------------------------------\n-- Events 846 and 850 hide the pact (bit 6) without SMN and the mount (bit 7) without the trainer's whistle.\n-- A repeat puts the quest back in the log.\n-- Leepe-Hoppe plays 850 and 851 in place of 846 and 847 from then on.\n-----------------------------------\nlocal windurstWatersID = zones[xi.zone.WINDURST_WATERS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.THE_MOONLIT_PATH)\n\nquest.reward =\n{\n    fame     = 60,\n    fameArea = xi.fameArea.WINDURST,\n    title    = xi.title.HEIR_OF_THE_NEW_MOON,\n}\n\nlocal avatarWhispers =\n{\n    xi.keyItem.WHISPER_OF_FLAMES,\n    xi.keyItem.WHISPER_OF_TREMORS,\n    xi.keyItem.WHISPER_OF_TIDES,\n    xi.keyItem.WHISPER_OF_GALES,\n    xi.keyItem.WHISPER_OF_FROST,\n    xi.keyItem.WHISPER_OF_STORMS,\n}\n\nlocal rewardItems =\n{\n    [1] = xi.item.FENRIRS_STONE,\n    [2] = xi.item.FENRIRS_CAPE,\n    [3] = xi.item.FENRIRS_TORQUE,\n    [4] = xi.item.FENRIRS_EARRING,\n    [5] = xi.item.ANCIENTS_KEY,\n}\n\nlocal function turnInOnEventFinish(player, csid, option, npc)\n    -- Retail does not advance the quest on an escaped cutscene.\n    if option < 1 or option > 8 then\n        return\n    end\n\n    if option <= 5 then\n        if not npcUtil.giveItem(player, rewardItems[option]) then\n            return\n        end\n    elseif option == 6 then\n        npcUtil.giveCurrency(player, 'gil', 15000)\n    elseif option == 7 then\n        player:addSpell(xi.magic.spell.FENRIR, { silentLog = true })\n        player:messageText(npc, windurstWatersID.text.FENRIR_UNLOCKED, false, 6)\n    elseif option == 8 then\n        npcUtil.giveKeyItem(player, xi.keyItem.FENRIR_WHISTLE)\n    end\n\n    quest:complete(player)\n    player:delKeyItem(xi.keyItem.WHISPER_OF_THE_MOON)\n    quest:setTimedVar(player, 'Timer', NextJstDay())\n\n    -- quest:complete() wipes the vars. Set again so Leepe-Hoppe plays 851 in place of 847.\n    if csid == 850 then\n        quest:setVar(player, 'Repeat', 1)\n    end\n\n    if\n        player:getNation() == xi.nation.WINDURST and\n        player:getRank(xi.nation.WINDURST) == 10 and\n        player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_PROMISE)\n    then\n        npcUtil.giveKeyItem(player, xi.keyItem.DARK_MANA_ORB)\n    end\nend\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 6\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Leepe-Hoppe'] = quest:progressEvent(842, 0, xi.item.CARBUNCLES_RUBY),\n\n            onEventFinish =\n            {\n                [842] = function(player, csid, option, npc)\n                    if option == 2 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.FULL_MOON_FOUNTAIN] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.MOONLIT_PATH then\n                        player:delKeyItem(xi.keyItem.MOON_BAUBLE)\n                        npcUtil.giveKeyItem(player, xi.keyItem.WHISPER_OF_THE_MOON)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Leepe-Hoppe'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.MOON_BAUBLE) then\n                        return quest:event(845, 0, xi.item.CARBUNCLES_RUBY, xi.keyItem.MOON_BAUBLE) -- Reminder: take the moon bauble to the Full Moon Fountain.\n                    end\n\n                    if not player:hasKeyItem(xi.keyItem.WHISPER_OF_THE_MOON) then\n                        for _, whisper in ipairs(avatarWhispers) do\n                            if not player:hasKeyItem(whisper) then\n                                return quest:event(843, 0, xi.item.CARBUNCLES_RUBY) -- Reminder: gather the six whispers.\n                            end\n                        end\n\n                        return quest:progressEvent(844, 0, xi.item.CARBUNCLES_RUBY, xi.keyItem.MOON_BAUBLE)\n                    end\n\n                    -- Set bits hide reward menu options.\n                    local rewardMask = 0\n\n                    for option, itemId in pairs(rewardItems) do\n                        if player:hasItem(itemId) then\n                            rewardMask = utils.mask.setBit(rewardMask, option - 1, true)\n                        end\n                    end\n\n                    if player:hasSpell(xi.magic.spell.FENRIR) or not player:hasJob(xi.job.SMN) then\n                        rewardMask = utils.mask.setBit(rewardMask, 6, true)\n                    end\n\n                    if\n                        player:hasKeyItem(xi.keyItem.FENRIR_WHISTLE) or\n                        not player:hasKeyItem(xi.keyItem.TRAINERS_WHISTLE)\n                    then\n                        rewardMask = utils.mask.setBit(rewardMask, 7, true)\n                    end\n\n                    if quest:getVar(player, 'Repeat') == 1 then\n                        return quest:progressEvent(850, 0, xi.item.FENRIRS_EARRING, xi.item.ANCIENTS_KEY, xi.item.CARBUNCLES_RUBY, rewardMask, xi.item.FENRIRS_STONE, xi.item.FENRIRS_CAPE)\n                    else\n                        return quest:progressEvent(846, 0, xi.item.FENRIRS_EARRING, xi.item.ANCIENTS_KEY, xi.item.CARBUNCLES_RUBY, rewardMask, xi.item.FENRIRS_STONE, xi.item.FENRIRS_CAPE)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [844] = function(player, csid, option, npc)\n                    -- Retail does not advance the quest on an escaped cutscene.\n                    if option ~= 0 then\n                        return\n                    end\n\n                    npcUtil.giveKeyItem(player, xi.keyItem.MOON_BAUBLE)\n\n                    for _, whisper in ipairs(avatarWhispers) do\n                        player:delKeyItem(whisper)\n                    end\n                end,\n\n                [846] = turnInOnEventFinish,\n                [850] = turnInOnEventFinish,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Leepe-Hoppe'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Repeatable once per JST day.\n                    if quest:getVar(player, 'Timer') == 0 then\n                        return quest:progressEvent(848, 0, xi.item.CARBUNCLES_RUBY, xi.keyItem.MOON_BAUBLE)\n                    elseif quest:getVar(player, 'Repeat') == 1 then\n                        return quest:event(851, 0, xi.item.CARBUNCLES_RUBY, xi.item.ANCIENTS_KEY, xi.item.CARBUNCLES_RUBY, 0, xi.item.FENRIRS_STONE, xi.item.FENRIRS_CAPE)\n                    else\n                        return quest:event(847, 0, xi.item.CARBUNCLES_RUBY)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [848] = function(player, csid, option, npc)\n                    if option == 2 then\n                        player:delQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_MOONLIT_PATH)\n                        npcUtil.giveKeyItem(player, xi.keyItem.MOON_BAUBLE)\n                        quest:begin(player)\n                        quest:setVar(player, 'Repeat', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Toraimarai_Turmoil.lua"]={["Path"]="scripts/quests/windurst/Toraimarai_Turmoil.lua",["SHA256"]="0a996a045385e5f51996c62e8f3ec134d7d80a5137a70d2298213c7fe733e2ba",["Text"]="-----------------------------------\n-- Toraimarai Turmoil\n-----------------------------------\n-- !addquest 2 80\n-- Ohbiru-Dohbiru : !pos 23 -5 -193 238\n-- Leepe-Hoppe    ! !pos -131 20 -174 238\n-- Polikal-Ramikal: !pos 15 -18 195 239\n-- Yoran-Oran     : !pos -110 -14 203 239\n-- Giddeus Spring : !pos -258 -2 -249 145\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.TORAIMARAI_TURMOIL)\n\nquest.reward =\n{\n    gil      = 4500,\n    fame     = 16,\n    fameArea = xi.fameArea.WINDURST,\n    title    = xi.title.CERTIFIED_RHINOSTERY_VENTURER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.BLUE_RIBBON_BLUES) and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 6 and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Ohbiru-Dohbiru'] = quest:progressEvent(785, 4500, xi.keyItem.RHINOSTERY_CERTIFICATE, xi.item.STARMITE_SHELL),\n\n            onEventFinish =\n            {\n                [785] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.RHINOSTERY_CERTIFICATE)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        -- Initial completion\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Ohbiru-Dohbiru'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.STARMITE_SHELL, 3 } }) then\n                        return quest:progressEvent(791)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:event(786, 4500, xi.keyItem.RHINOSTERY_CERTIFICATE, xi.item.STARMITE_SHELL) -- Reminder text.\n                end,\n            },\n\n            ['Leepe-Hoppe'] = quest:event(790, 0, xi.keyItem.RHINOSTERY_CERTIFICATE),\n\n            onEventFinish =\n            {\n                [791] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Polikal-Ramikal'] = quest:event(391),\n\n            ['Yoran-Oran'] = quest:event(392),\n        },\n    },\n\n    {\n        -- Repeat completion\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Ohbiru-Dohbiru'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeHasExactly(trade, { { xi.item.STARMITE_SHELL, 3 } })\n                    then\n                        return quest:progressEvent(791)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:event(786, 4500, xi.keyItem.RHINOSTERY_CERTIFICATE, xi.item.STARMITE_SHELL) -- Reminder text.\n                    else\n                        return quest:event(795, 4500, 0, xi.item.STARMITE_SHELL) -- Repeat dialog.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [791] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        quest:setVar(player, 'Prog', 0)\n                        player:confirmTrade()\n                        player:addFame(xi.fameArea.WINDURST, 16)\n                        npcUtil.giveCurrency(player, 'gil', 4500)\n                    end\n                end,\n\n                [795] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Waking_Dreams.lua"]={["Path"]="scripts/quests/windurst/Waking_Dreams.lua",["SHA256"]="1408999224ce087e9e0000ab0de082bec6cb3d5263e73dda25af899de5a5e750",["Text"]="-----------------------------------\n-- Waking Dreams\n-----------------------------------\n-- Log ID: 2, Quest ID: 93\n-- Kerutoto : !pos 13 -5 -157 238\n-----------------------------------\n-- Event 920 hides the pact option (bit 5) for players who have not unlocked SMN or already know it.\n-- A seventh event param of 1 plays Kerutoto's repeat lines in 918 and 920.\n-----------------------------------\nlocal windurstWatersID = zones[xi.zone.WINDURST_WATERS]\n-----------------------------------\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.WAKING_DREAMS)\n\nlocal rewardItems =\n{\n    [1] = xi.item.DIABOLOSS_POLE,\n    [2] = xi.item.DIABOLOSS_EARRING,\n    [3] = xi.item.DIABOLOSS_RING,\n    [4] = xi.item.DIABOLOSS_TORQUE,\n}\n\n-- Setup reward table to display available awards in event properly\nlocal function getAvailableRewards(player)\n    local rewardMask = 0\n\n    for bit, itemId in pairs(rewardItems) do\n        if player:hasItem(itemId) then\n            rewardMask = utils.mask.setBit(rewardMask, bit - 1, true)\n        end\n    end\n\n    if\n        player:hasSpell(xi.magic.spell.DIABOLOS) or\n        not player:hasJob(xi.job.SMN)\n    then\n        rewardMask = utils.mask.setBit(rewardMask, 5, true)\n    end\n\n    return rewardMask\nend\n\nlocal function giveQuestReward(player, npc, option)\n    if option <= 4 then\n        return npcUtil.giveItem(player, rewardItems[option])\n    elseif option == 5 then\n        npcUtil.giveCurrency(player, 'gil', 15000)\n    elseif option == 6 then\n        player:addSpell(xi.magic.spell.DIABOLOS, { silentLog = true })\n        player:messageText(npc, windurstWatersID.text.DIABOLOS_UNLOCKED, false, 6)\n    end\n\n    return true\nend\n\nquest.sections =\n{\n    -- Section 1: Quest available (first time)\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.DARKNESS_NAMED)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Kerutoto'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(918)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [918] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.VIAL_OF_DREAM_INCENSE)\n                end,\n            },\n        },\n    },\n\n    -- Section 2: Quest accepted (First time)\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Kerutoto'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Quest complete.\n                    if player:hasKeyItem(xi.keyItem.WHISPER_OF_DREAMS) then\n                        return quest:progressEvent(920, xi.item.DIABOLOSS_POLE, xi.item.DIABOLOSS_EARRING, xi.item.DIABOLOSS_RING, xi.item.DIABOLOSS_TORQUE, 0, 0, 0, getAvailableRewards(player))\n\n                    -- 1-time optional dialog.\n                    elseif quest:getVar(player, 'Option') == 0 then\n                        return quest:progressEvent(919)\n\n                    -- In-quest default.\n                    else\n                        return quest:event(789)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [919] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n\n                [920] = function(player, csid, option, npc)\n                    -- Retail does not advance the quest on an escaped cutscene.\n                    if option < 1 or option > 6 then\n                        return\n                    end\n\n                    if not giveQuestReward(player, npc, option) then\n                        return\n                    end\n\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.WINDURST, 60)\n                        player:delKeyItem(xi.keyItem.WHISPER_OF_DREAMS)\n                        player:setCharVar('Darkness_Named_date', JstMidnight())\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section 3: Quest completed (repeats)\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Kerutoto'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Time lockout. Retail keeps the in-quest lines until the next offer.\n                    if GetSystemTime() < player:getCharVar('Darkness_Named_date') then\n                        return quest:event(789):replaceDefault()\n\n                    -- Quest complete.\n                    elseif player:hasKeyItem(xi.keyItem.WHISPER_OF_DREAMS) then\n                        return quest:progressEvent(920, xi.item.DIABOLOSS_POLE, xi.item.DIABOLOSS_EARRING, xi.item.DIABOLOSS_RING, xi.item.DIABOLOSS_TORQUE, 0, 0, 1, getAvailableRewards(player))\n\n                    -- \"Re-start\" quest\n                    elseif not player:hasKeyItem(xi.keyItem.VIAL_OF_DREAM_INCENSE) then\n                        return quest:progressEvent(918, 0, 0, 0, 0, 0, 0, 1)\n\n                    -- 1-time optional dialog.\n                    elseif quest:getVar(player, 'Option') == 0 then\n                        return quest:progressEvent(919)\n\n                    -- In-quest default.\n                    else\n                        return quest:event(789)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [918] = function(player, csid, option, npc)\n                    -- \"Not yet.\" returns the escape value.\n                    if option == 1 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.VIAL_OF_DREAM_INCENSE)\n                    end\n                end,\n\n                [919] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n\n                [920] = function(player, csid, option, npc)\n                    -- Retail does not advance the quest on an escaped cutscene.\n                    if option < 1 or option > 6 then\n                        return\n                    end\n\n                    if not giveQuestReward(player, npc, option) then\n                        return\n                    end\n\n                    player:delKeyItem(xi.keyItem.WHISPER_OF_DREAMS)\n                    player:setCharVar('Darkness_Named_date', JstMidnight())\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Water_Way_to_Go.lua"]={["Path"]="scripts/quests/windurst/Water_Way_to_Go.lua",["SHA256"]="2d3290c340d5bc61d50f39e2fc9b34095fc4abeeb346b0c3e3b8259a4599f41f",["Text"]="-----------------------------------\n-- Water Way to Go\n-----------------------------------\n-- !addquest 2 16\n-- Ohbiru-Dohbiru : !pos 23 -5 -193 238\n-- Giddeus Spring : !pos -258 -2 -249 145\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.WATER_WAY_TO_GO)\n\nquest.reward =\n{\n    fame     = 16,\n    fameArea = xi.fameArea.WINDURST,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.OVERNIGHT_DELIVERY) and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 3 and\n                not xi.quest.getMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.OVERNIGHT_DELIVERY)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Ohbiru-Dohbiru'] = quest:progressEvent(352, 0, xi.item.CANTEEN_OF_GIDDEUS_WATER),\n\n            onEventFinish =\n            {\n                [352] = function(player, csid, option, npc)\n                    if\n                        option == 0 and\n                        npcUtil.giveItem(player, xi.item.RHINOSTERY_CANTEEN)\n                    then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.GIDDEUS] =\n        {\n            ['Giddeus_Spring'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.RHINOSTERY_CANTEEN, 1 } }) then\n                        return quest:progressEvent(55)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [55] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.CANTEEN_OF_GIDDEUS_WATER) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Ohbiru-Dohbiru'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.CANTEEN_OF_GIDDEUS_WATER, 1 } }) then\n                        return quest:progressEvent(355, 900)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if\n                        not player:findItem(xi.item.RHINOSTERY_CANTEEN) and\n                        not player:findItem(xi.item.CANTEEN_OF_GIDDEUS_WATER)\n                    then\n                        return quest:progressEvent(354)\n                    else\n                        return quest:event(353)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [354] = function(player, csid, option, npc)\n                    npcUtil.giveItem(player, xi.item.RHINOSTERY_CANTEEN)\n                end,\n\n                [355] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        -- Note: Message display for gil reward is handled by the event\n                        player:addGil(900)\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Quest complete section.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.GIDDEUS] =\n        {\n            ['Giddeus_Spring'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeMatches(trade, { { xi.item.RHINOSTERY_CANTEEN, 1 } })\n                    then\n                        return quest:progressEvent(55)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [55] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.CANTEEN_OF_GIDDEUS_WATER) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Ohbiru-Dohbiru'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.CANTEEN_OF_GIDDEUS_WATER, 1 } }) then\n                        return quest:progressEvent(355, 900)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    -- Default after completing without zoning.\n                    if quest:getMustZone(player) then\n                        return quest:event(356, 0, xi.item.CANTEEN_OF_GIDDEUS_WATER)\n                    end\n\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    -- Re-start quest.\n                    if questProgress == 0 then\n                        if player:getFameLevel(xi.fameArea.WINDURST) < 5 then\n                            return quest:progressEvent(352, 0, xi.item.CANTEEN_OF_GIDDEUS_WATER)\n                        end\n\n                    -- Quest re-started.\n                    elseif questProgress == 1 then\n                        if\n                            not player:findItem(xi.item.RHINOSTERY_CANTEEN) and\n                            not player:findItem(xi.item.CANTEEN_OF_GIDDEUS_WATER)\n                        then\n                            return quest:progressEvent(354)\n                        else\n                            return quest:event(353)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [352] = function(player, csid, option, npc)\n                    if\n                        option == 0 and\n                        npcUtil.giveItem(player, xi.item.RHINOSTERY_CANTEEN)\n                    then\n                        quest:begin(player)\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [354] = function(player, csid, option, npc)\n                    npcUtil.giveItem(player, xi.item.RHINOSTERY_CANTEEN)\n                end,\n\n                [355] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:addGil(900)\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Wondering_Minstrel.lua"]={["Path"]="scripts/quests/windurst/Wondering_Minstrel.lua",["SHA256"]="0c51d921058e0b9a777653b2199badd90542882c29c23a434510bea11deb3dbc",["Text"]="-----------------------------------\n-- Wondering Minstrel\n-----------------------------------\n-- Log ID: 2, Quest ID: 6\n-- !addquest 2 6\n-- Jatan-Paratan : !pos -59.998 -4.105 19.775 238\n-- Yuli Yaam     : !pos -62.241 -3.500 21.683 238\n-- Yung Yaam     : !pos -65.622 -3.800 27.019 238\n-- Aramu-Paramu  : !pos -66.924 -3.800 26.038 238\n-- Ruslan        : !pos -19.293 -0.100 -56.648 245\n-----------------------------------\n-- Jatan-Paratan will not offer the quest until the player tells him they have no recollection of his playing at all (option 3).\n-- On quest completion, all Tavern NPCs involved offer unique dialogue about the events that transpired until the player zones.\n-- Then they all revert to normal dialogue.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.WONDERING_MINSTREL)\n\nquest.reward =\n{\n    fame     = 50,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.FAERIE_PICCOLO,\n    title    = xi.title.DOWN_PIPER_PIPE_UPPERER,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 5\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Jatan-Paratan'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(633) -- Asks what the player made of his playing. Correct option neded to trigger next event.\n                    else\n                        return quest:progressEvent(634) -- Offers the quest\n                    end\n                end,\n            },\n\n            ['Yuli_Yaam'] = quest:event(637),\n            ['Yung_Yaam'] = quest:event(636),\n\n            onEventFinish =\n            {\n                [633] = function(player, csid, option, npc)\n                    if option == 3 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [634] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Ruslan'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(10009, 0, xi.item.PIECE_OF_ROSEWOOD_LUMBER) -- Asks for the lumber.\n                    else\n                        return quest:event(10010, 0, xi.item.PIECE_OF_ROSEWOOD_LUMBER) -- Rminder.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10009] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Jatan-Paratan'] =\n            {\n                onTrade = function(player, npc, trade)\n                    -- The lumber means nothing to him until Ruslan has explained what it is for.\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        npcUtil.tradeMatches(trade, { { xi.item.PIECE_OF_ROSEWOOD_LUMBER, 1 } })\n                    then\n                        return quest:progressEvent(638) -- Finishes the quest\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:event(635)\n                end,\n            },\n\n            ['Aramu-Paramu'] = quest:event(683),\n            ['Yuli_Yaam']    = quest:event(637),\n            ['Yung_Yaam']    = quest:event(636),\n\n            onEventFinish =\n            {\n                [638] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:needToZone(true)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Ruslan'] =\n            {\n                onTrigger = function(player, npc)\n                    if math.randomInt(1, 3) == 1 then\n                        return quest:event(10011)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Aramu-Paramu'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:needToZone() then\n                        return quest:event(684)\n                    end\n                end,\n            },\n\n            ['Jatan-Paratan'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:needToZone() then\n                        return quest:event(639)\n                    end\n                end,\n            },\n\n            ['Yuli_Yaam'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:needToZone() then\n                        return quest:event(641)\n                    end\n                end,\n            },\n\n            ['Yung_Yaam'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:needToZone() then\n                        return quest:event(643)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/zones/Aht_Urhgan_Whitegate/npcs/Ghatsad.lua"]={["Path"]="scripts/zones/Aht_Urhgan_Whitegate/npcs/Ghatsad.lua",["SHA256"]="4d5b991404a607128c7d441956587155cfd65338862762bdfcef3b20d1a61d9e",["Text"]="-----------------------------------\n-- Area: Aht Urhgan Whitegate\n--  NPC: Ghatsad\n-- Involved in quest: No Strings Attached\n-- !pos 34.325 -7.804 57.511 50\n-----------------------------------\nlocal ID = zones[xi.zone.AHT_URHGAN_WHITEGATE]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\n--cs 620 - new frame - param 6: itemid payment param 7: number of payment param 8: bitpack choices (bit 0 no thanks, bit 1 VE, bit 2 SS, bit 3 SW)\n--cs 621 - new frame (if canceled previous)\n--cs 622 - bring me mats\n--cs 624 - all mats, just need payment\n--cs 625 - thanks, have everything, come back later\n--cs 626 - come back later\n--cs 627 - automaton frame done (param 2: frame)\n--cs 628 - you can customise automaton by changing frame\n--cs 629 - you can alter automatons abilities and character by equipping attachments (what are these last 2 for?)\n--cs 900 - start soulsoother/spiritreaver\n--cs 901 - start second head\n--cs 902 - start work on chosen head\n--cs 903 - head almost done\n--cs 904 - give coffee\n--cs 905 - head complete\n\n-- Since every outcome includes a head, track number unlocked based on this.\n-- This is used to calculate the cost of additional items, and provide certain\n-- event parameters (numUnlockedHeads).\nlocal automatonHeads =\n{\n    xi.item.VALOREDGE_HEAD,\n    xi.item.SHARPSHOT_HEAD,\n    xi.item.STORMWAKER_HEAD,\n    xi.item.SOULSOOTHER_HEAD,\n    xi.item.SPIRITREAVER_HEAD,\n}\n\nlocal unlockCost =\n{\n    [0] = { xi.item.IMPERIAL_SILVER_PIECE,  3 },\n    [1] = { xi.item.IMPERIAL_MYTHRIL_PIECE, 3 },\n    [2] = { xi.item.IMPERIAL_GOLD_PIECE,    1 },\n    [3] = { xi.item.IMPERIAL_MYTHRIL_PIECE, 2 },\n    [4] = { xi.item.IMPERIAL_MYTHRIL_PIECE, 4 },\n}\n\n-- This table is keyed by the initial attachmentStatus for each Head/Frame\n-- combination that can be purchased (Valoredge, Sharpshot, Stormwaker)\nlocal headAndFrameItems =\n{\n    [2] = { xi.item.BRASS_SHEET,              xi.item.WAMOURA_COCOON,          xi.item.CHUNK_OF_IMPERIAL_CERMET,  xi.item.PATAS          },\n    [3] = { xi.item.PIECE_OF_ROSEWOOD_LUMBER, xi.item.SQUARE_OF_KARAKUL_CLOTH, xi.item.SQUARE_OF_KARAKUL_LEATHER, xi.item.HEAVY_CROSSBOW },\n    [4] = { xi.item.SPOOL_OF_GOLD_THREAD,     xi.item.SQUARE_OF_VELVET_CLOTH,  xi.item.SQUARE_OF_WAMOURA_CLOTH,   xi.item.BRASS_RING     },\n}\n\n-- Depending on item traded, a random range is provided for number of\n-- Vana'diel days to wait until completed.\nlocal turbanItems =\n{\n    [xi.item.WHITE_PUPPET_TURBAN] =\n    {\n        [xi.item.SCROLL_OF_CURE_V ] = { 2, 4 },\n        [xi.item.SCROLL_OF_REGEN  ] = { 3, 4 },\n        [xi.item.SCROLL_OF_CURE_II] = { 5, 5 },\n    },\n\n    [xi.item.BLACK_PUPPET_TURBAN] =\n    {\n        [xi.item.SCROLL_OF_STONE_IV  ] = { 2, 4 },\n        [xi.item.SCROLL_OF_ABSORB_INT] = { 3, 4 },\n        [xi.item.SCROLL_OF_FIRE      ] = { 5, 5 },\n    },\n}\n\nlocal function getWaitRange(turbanType, trade)\n    for k, v in pairs(turbanItems[turbanType]) do\n        if trade:getItemQty(k) == 1 then\n            return v\n        end\n    end\n\n    return { 0, 0 }\nend\n\nlocal function getNumUnlockedHeads(player)\n    local headCount = 0\n\n    for _, v in ipairs(automatonHeads) do\n        if player:hasAttachment(v) then\n            headCount = headCount + 1\n        end\n    end\n\n    return headCount\nend\n\nlocal function getHeadMask(player)\n    local headMask = 0\n\n    for k, v in ipairs(automatonHeads) do\n        if player:hasAttachment(v) then\n            headMask = headMask + bit.lshift(1, k)\n        end\n    end\n\n    return headMask\nend\n\nlocal function hasRequiredMats(trade, headFrameKey)\n    for _, v in ipairs(headAndFrameItems[headFrameKey]) do\n        if trade:getItemQty(v) ~= 1 then\n            return false\n        end\n    end\n\n    return true\nend\n\nlocal function satisfy_attachment(player, newAttachmentStatus)\n    player:tradeComplete()\n    player:setCharVar('PUP_AttachmentStatus', newAttachmentStatus)\n    player:setCharVar('PUP_AttachmentReady', VanadielUniqueDay() + 1)\n    player:startEvent(625)\nend\n\nlocal function play_event902(player, newAttachmentStatus, waitDays)\n    -- Add safety if an invalid item was traded\n    if waitDays == nil then\n        return\n    end\n\n    player:tradeComplete()\n    player:setCharVar('PUP_AttachmentStatus', newAttachmentStatus)\n    player:setCharVar('PUP_AttachmentReady', VanadielUniqueDay() + waitDays)\n    player:setCharVar('PUP_nextCoffeeTrade', VanadielUniqueDay() + 1)\n    player:startEvent(902)\nend\n\nentity.onTrade = function(player, npc, trade)\n    local attachmentStatus   = player:getCharVar('PUP_AttachmentStatus')\n    local numUnlockedHeads   = getNumUnlockedHeads(player)\n    local attachmentReadyDay = player:getCharVar('PUP_AttachmentReady')\n    local attachmentReady    = attachmentReadyDay ~= 0 and attachmentReadyDay <= VanadielUniqueDay()\n    local tradeHasPayment    = trade:getItemQty(unlockCost[numUnlockedHeads][1]) == unlockCost[numUnlockedHeads][2]\n\n    -- Initial Trade: Has Materials + Payment, or just Materials\n    if attachmentStatus >= 2 and attachmentStatus <= 4 then\n        if hasRequiredMats(trade, attachmentStatus) then\n            local slotCount = trade:getSlotCount()\n\n            if slotCount == 4 then\n                player:tradeComplete()\n                player:setCharVar('PUP_AttachmentStatus', attachmentStatus + 3)\n                player:startEvent(624, 0, 0, 0, 0, 0, unlockCost[numUnlockedHeads][1], unlockCost[numUnlockedHeads][2])\n            elseif slotCount == 5 and tradeHasPayment then\n                satisfy_attachment(player, attachmentStatus + 6)\n            end\n        end\n\n    -- Traded Materials previously, and is now trading Payment\n    elseif\n        attachmentStatus >= 5 and\n        attachmentStatus <= 7 and\n        tradeHasPayment and\n        trade:getSlotCount() == 1\n    then\n        satisfy_attachment(player, attachmentStatus + 3)\n\n    -- Soulsoother or Spiritreaver Trade, requires all items up front\n    elseif\n        (numUnlockedHeads == 3 and attachmentStatus == 11) or\n        (numUnlockedHeads == 4 and attachmentStatus == 14)\n    then\n        if trade:getSlotCount() == 3 then\n            if tradeHasPayment then\n                if\n                    trade:getItemQty(xi.item.WHITE_PUPPET_TURBAN) == 1 and\n                    not player:hasAttachment(xi.item.SOULSOOTHER_HEAD)\n                then\n                    local range = getWaitRange(xi.item.WHITE_PUPPET_TURBAN, trade)\n\n                    play_event902(player, 12, math.randomInt(range[1], range[2]))\n                elseif\n                    trade:getItemQty(xi.item.BLACK_PUPPET_TURBAN) == 1 and\n                    not player:hasAttachment(xi.item.SPIRITREAVER_HEAD)\n                then\n                    local range = getWaitRange(xi.item.BLACK_PUPPET_TURBAN, trade)\n\n                    play_event902(player, 13, math.randomInt(range[1], range[2]))\n                end\n            end\n        end\n\n    -- Imperial Coffee Trade to reduce time remaining.\n    elseif\n        (attachmentStatus == 12 or attachmentStatus == 13) and\n        not attachmentReady and\n        player:getCharVar('PUP_nextCoffeeTrade') <= VanadielUniqueDay() and\n        npcUtil.tradeMatches(trade, { { xi.item.CUP_OF_IMPERIAL_COFFEE, 1 } })\n    then\n        player:startEvent(904)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if not player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.NO_STRINGS_ATTACHED) then\n        player:startEvent(256)\n        return\n    end\n\n    if player:getMainJob() ~= xi.job.PUP then\n        player:startEvent(256)\n        return\n    end\n\n    local automatonName       = player:getAutomatonName()\n    local numUnlockedHeads    = getNumUnlockedHeads(player)\n    local attachmentStatus    = player:getCharVar('PUP_AttachmentStatus')\n    local unlockedAttachments = getHeadMask(player)\n    local attachmentReadyDay  = player:getCharVar('PUP_AttachmentReady')\n    local attachmentReady     = attachmentReadyDay ~= 0 and attachmentReadyDay <= VanadielUniqueDay()\n\n    -- attachment status:\n    --  0 - none\n    --  1 - declined a new frame\n    --  2 - accepted valoredge\n    --  3 - accepted sharphot\n    --  4 - accepted stormwaker\n    --  5 - paid mats for valoredge\n    --  6 - paid mats for sharpshot\n    --  7 - paid mats for stormwaker\n    --  8 - paid mats + coins for valoredge\n    --  9 - paid mats + coins for sharpshot\n    -- 10 - paid mats + coins for stormwaker\n    -- 11 - asked about soulsoother/spiritreaver\n    -- 12 - paid for soulsoother\n    -- 13 - paid for spiritreaver\n    -- 14 - asked about soulsoother/spiritreaver (after obtaining the first)\n\n    -- Has not Accepted or Declined a new Head (or Head/Frame combination)\n    if\n        attachmentStatus == 0 and\n        player:getMainLvl() >= 10 + numUnlockedHeads * 10\n    then\n        if numUnlockedHeads < 3 then\n            player:startEventString(620, automatonName, automatonName, automatonName, automatonName, numUnlockedHeads, 0, 0, 0, 0, unlockCost[numUnlockedHeads][1], unlockCost[numUnlockedHeads][2], unlockedAttachments)\n        elseif numUnlockedHeads == 3 then\n            player:startEventString(900, automatonName, automatonName, automatonName, automatonName, 0, 0, 0, 0, 0, unlockCost[numUnlockedHeads][1], unlockCost[numUnlockedHeads][2])\n        elseif numUnlockedHeads == 4 then\n            if unlockedAttachments == 30 then\n                player:startEventString(901, automatonName, automatonName, automatonName, automatonName, 1, 0, 0, 0, 0, unlockCost[numUnlockedHeads][1], unlockCost[numUnlockedHeads][2])\n            elseif unlockedAttachments == 46 then\n                player:startEventString(901, automatonName, automatonName, automatonName, automatonName, 0, 0, 0, 0, 0, unlockCost[numUnlockedHeads][1], unlockCost[numUnlockedHeads][2])\n            end\n        end\n\n    -- Declined a new Head or Head/Frame combination\n    elseif attachmentStatus == 1 then\n        player:startEvent(621, 0, 0, 0, 0, 0, unlockCost[numUnlockedHeads][1], unlockCost[numUnlockedHeads][2], unlockedAttachments)\n\n    -- Accepted a Head/Frame Combination, but has not provided any payment\n    elseif attachmentStatus >= 2 and attachmentStatus <= 4 then\n        local option = player:getCharVar('PUP_AttachmentOption')\n        player:startEvent(622, 0, option, 0, 0, 0, unlockCost[numUnlockedHeads][1], unlockCost[numUnlockedHeads][2])\n\n    -- Paid Mats for Head/Frame Combination, but needs to provide Currency\n    elseif attachmentStatus >= 5 and attachmentStatus <= 7 then\n        player:startEvent(624, 0, 0, 0, 0, 0, unlockCost[numUnlockedHeads][1], unlockCost[numUnlockedHeads][2])\n\n    -- Paid in Full (Mats & Currency) for Head/Frame Combination\n    elseif attachmentStatus >= 8 and attachmentStatus <= 10 then\n        if not attachmentReady then\n            player:startEvent(626)\n        else\n            local param6 = attachmentStatus - 7\n\n            player:startEventString(627, automatonName, automatonName, automatonName, automatonName, 0, param6)\n        end\n\n    -- Asked about Soulsoother/Spiritreaver Head\n    elseif attachmentStatus == 11 and numUnlockedHeads == 3 then\n        player:startEventString(900, automatonName, automatonName, automatonName, automatonName, 0, 0, 1, 0, 0, unlockCost[numUnlockedHeads][1], unlockCost[numUnlockedHeads][2])\n\n    -- Paid for Soulsoother/Spiritreaver Head\n    elseif attachmentStatus == 12 or attachmentStatus == 13 then\n        local attachmentDaysRemaining = attachmentReadyDay - VanadielUniqueDay()\n\n        if not attachmentReady then\n            player:startEvent(903, attachmentDaysRemaining, 1)\n        else\n            if attachmentDaysRemaining > 0 then\n                player:startEvent(903, attachmentDaysRemaining, 0)\n            else\n                player:startEvent(905, attachmentStatus - 12)\n            end\n        end\n\n    -- Ask about other head, after obtaining one already (Spiritreaver or Soulsoother)\n    elseif attachmentStatus == 14 then\n        if unlockedAttachments == 30 then\n            player:startEventString(901, automatonName, automatonName, automatonName, automatonName, 1, 0, 1, 0, 0, unlockCost[numUnlockedHeads][1], unlockCost[numUnlockedHeads][2])\n        elseif unlockedAttachments == 46 then\n            player:startEventString(901, automatonName, automatonName, automatonName, automatonName, 0, 0, 1, 0, 0, unlockCost[numUnlockedHeads][1], unlockCost[numUnlockedHeads][2])\n        end\n\n    -- Default PUP actions after first Unlock\n    elseif numUnlockedHeads > 0 then\n        local rand = math.randomInt(1, 2)\n        if rand == 1 then\n            player:startEvent(628)\n        else\n            player:startEventString(629, automatonName, automatonName, automatonName, automatonName)\n        end\n    end\nend\n\nentity.onEventUpdate = function(player, csid, option, npc)\n    if csid == 620 then -- Collecting option for CS 622 param 2\n        if option == 1 then\n            player:setCharVar('PUP_AttachmentOption', option)\n        elseif option == 2 then\n            player:setCharVar('PUP_AttachmentOption', option)\n        elseif option == 3 then\n            player:setCharVar('PUP_AttachmentOption', option)\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if\n        (csid == 620 or csid == 621) and\n        option >= 0 and\n        option <= 3\n    then\n        player:setCharVar('PUP_AttachmentStatus', option + 1)\n    elseif csid == 627 then\n        local attachmentStatus = player:getCharVar('PUP_AttachmentStatus')\n\n        if attachmentStatus == 8 then\n            player:unlockAttachment(xi.item.VALOREDGE_FRAME)\n            player:unlockAttachment(xi.item.VALOREDGE_HEAD)\n            player:messageSpecial(ID.text.AUTOMATON_VALOREDGE_UNLOCK)\n            player:setCharVar('PUP_AttachmentOption', 0)\n        elseif attachmentStatus == 9 then\n            player:unlockAttachment(xi.item.SHARPSHOT_FRAME)\n            player:unlockAttachment(xi.item.SHARPSHOT_HEAD)\n            player:messageSpecial(ID.text.AUTOMATON_SHARPSHOT_UNLOCK)\n            player:setCharVar('PUP_AttachmentOption', 0)\n        elseif attachmentStatus == 10 then\n            player:unlockAttachment(xi.item.STORMWAKER_FRAME)\n            player:unlockAttachment(xi.item.STORMWAKER_HEAD)\n            player:messageSpecial(ID.text.AUTOMATON_STORMWAKER_UNLOCK)\n            player:setCharVar('PUP_AttachmentOption', 0)\n        end\n\n        player:setCharVar('PUP_AttachmentStatus', 0)\n        player:setCharVar('PUP_AttachmentReady', 0)\n    elseif csid == 900 then\n        player:setCharVar('PUP_AttachmentStatus', 11)\n    elseif csid == 901 then\n        player:setCharVar('PUP_AttachmentStatus', 14)\n\n    -- Coffee trade.\n    elseif csid == 904 then\n        player:setCharVar('PUP_AttachmentReady', player:getCharVar('PUP_AttachmentReady') - 1)\n        player:setCharVar('PUP_nextCoffeeTrade', VanadielUniqueDay() + 1)\n        player:tradeComplete()\n\n    elseif csid == 905 then\n        local attachmentStatus = player:getCharVar('PUP_AttachmentStatus')\n        local unlockedAttachments = getHeadMask(player)\n\n        if attachmentStatus == 12 then\n            player:unlockAttachment(xi.item.SOULSOOTHER_HEAD)\n            player:messageSpecial(ID.text.AUTOMATON_SOULSOOTHER_UNLOCK)\n        elseif attachmentStatus == 13 then\n            player:unlockAttachment(xi.item.SPIRITREAVER_HEAD)\n            player:messageSpecial(ID.text.AUTOMATON_SPIRITREAVER_UNLOCK)\n        elseif attachmentStatus == 14 and unlockedAttachments == 30 then\n            player:unlockAttachment(xi.item.SPIRITREAVER_HEAD)\n            player:messageSpecial(ID.text.AUTOMATON_SPIRITREAVER_UNLOCK)\n        elseif attachmentStatus == 14 and unlockedAttachments == 46 then\n            player:unlockAttachment(xi.item.SOULSOOTHER_HEAD)\n            player:messageSpecial(ID.text.AUTOMATON_SOULSOOTHER_UNLOCK)\n        end\n\n        player:setCharVar('PUP_AttachmentStatus', 0)\n        player:setCharVar('PUP_AttachmentReady', 0)\n        player:setCharVar('PUP_nextCoffeeTrade', 0)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Aht_Urhgan_Whitegate/npcs/Iruki-Waraki.lua"]={["Path"]="scripts/zones/Aht_Urhgan_Whitegate/npcs/Iruki-Waraki.lua",["SHA256"]="2d27ff47ae6433d02836aa2dc2f4c03187ee12defba36f9b2174c08eae87f997",["Text"]="-----------------------------------\n-- Area: Aht Urhgan Whitegate\n--  NPC: Iruki-Waraki\n--  Involved in quest: No Strings Attached\n-- !pos 101.329 -6.999 -29.042 50\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        npcUtil.tradeHas(trade, { xi.item.FLASK_OF_SLEEPING_POTION, xi.item.CUP_OF_CHAI }) and\n        player:getCharVar('OperationTeaTimeProgress') == 1\n    then\n        -- Chai, Sleeping Potion\n        player:startEvent(780)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local noStringsAttached = player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.NO_STRINGS_ATTACHED)\n    local theWaywardAutomaton = player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.THE_WAYWARD_AUTOMATON)\n    local theWaywardAutomatonProgress = player:getCharVar('TheWaywardAutomatonProgress')\n    local operationTeaTime = player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.OPERATION_TEATIME)\n    local operationTeaTimeProgress = player:getCharVar('OperationTeaTimeProgress')\n    local playerLvl = player:getMainLvl()\n    local playerJob = player:getMainJob()\n\n    --Quest: The Wayward Automaton\n    if\n        playerJob == xi.job.PUP and\n        playerLvl >= xi.settings.main.AF1_QUEST_LEVEL and\n        noStringsAttached == xi.questStatus.QUEST_COMPLETED and\n        theWaywardAutomaton == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(774) -- he tells you to help find his auto\n    elseif\n        theWaywardAutomaton == xi.questStatus.QUEST_ACCEPTED and\n        theWaywardAutomatonProgress == 1\n    then\n        player:startEvent(775) -- reminder about to head to Nashmau\n    elseif\n        theWaywardAutomaton == xi.questStatus.QUEST_ACCEPTED and\n        theWaywardAutomatonProgress == 3\n    then\n        player:startEvent(776) -- tell him you found Automaton\n    elseif\n        playerJob == xi.job.PUP and\n        playerLvl < xi.settings.main.AF2_QUEST_LEVEL and\n        theWaywardAutomaton == xi.questStatus.QUEST_COMPLETED\n    then\n        player:startEvent(777)\n    elseif\n        playerJob ~= xi.job.PUP and\n        theWaywardAutomaton == xi.questStatus.QUEST_COMPLETED\n    then\n        player:startEvent(777)\n    elseif\n        playerJob ~= xi.job.PUP and\n        noStringsAttached == xi.questStatus.QUEST_COMPLETED\n    then\n        player:startEvent(267) -- asking you how are you doing with your automaton\n\n    --Quest: Operation teatime\n    elseif\n        playerJob == xi.job.PUP and\n        playerLvl >= xi.settings.main.AF2_QUEST_LEVEL and\n        noStringsAttached == xi.questStatus.QUEST_COMPLETED and\n        theWaywardAutomaton == xi.questStatus.QUEST_COMPLETED and\n        operationTeaTime == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(778)\n    elseif\n        operationTeaTime == xi.questStatus.QUEST_ACCEPTED and\n        operationTeaTimeProgress == 1\n    then\n        player:startEvent(779) -- Reminds you to get items\n    elseif\n        operationTeaTime == xi.questStatus.QUEST_ACCEPTED and\n        operationTeaTimeProgress == 2\n    then\n        player:startEvent(781) -- Reminds you to get items\n    elseif operationTeaTime == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(777)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 774 then\n        player:setCharVar('TheWaywardAutomatonProgress', 1)\n        player:addQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.THE_WAYWARD_AUTOMATON)\n    elseif csid == 776 then\n        npcUtil.completeQuest(player, xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.THE_WAYWARD_AUTOMATON, { item = xi.item.TURBO_ANIMATOR, var = 'TheWaywardAutomatonProgress' })\n    elseif csid == 778 then\n        player:setCharVar('OperationTeaTimeProgress', 1)\n        player:addQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.OPERATION_TEATIME)\n    elseif csid == 780 then\n        player:setCharVar('OperationTeaTimeProgress', 2)\n        player:confirmTrade()\n    end\nend\n\nreturn entity\n"},["scripts/zones/Altar_Room/npcs/Stone_Lid.lua"]={["Path"]="scripts/zones/Altar_Room/npcs/Stone_Lid.lua",["SHA256"]="a097b4d1288e1611572b01b96c9e766a0e1d59fcd718579f1d000bb80d94ae65",["Text"]="-----------------------------------\n-- Area: Altar Room\n--  NPC: Stone Lid\n-- !pos -316.4390, 24.7654, 12.1590\n-----------------------------------\nlocal ID = zones[xi.zone.ALTAR_ROOM]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local moralmanifest = player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.A_MORAL_MANIFEST)\n    if\n        moralmanifest == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('moral') == 7\n    then\n        if trade:hasItemQty(xi.item.YAGUDO_HEADGEAR, 1) then -- Trade Yagudo Headgear\n            player:tradeComplete()\n            player:startEvent(50)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    -- local moralmanifest = player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.A_MORAL_MANIFEST)\n    local moral = player:getCharVar('moral')\n    local head = player:getEquipID(xi.slot.HEAD)\n    if moral == 5 and head == xi.item.YAGUDO_HEADGEAR then\n        player:startEvent(48)\n    elseif moral == 6 then\n        player:startEvent(49)\n    else\n        return\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 48 then\n        local mobs =\n        {\n            ID.mob.YAGUDO_AVATAR,\n            ID.mob.DUU_MASA_THE_ONECUT,\n            ID.mob.FEE_JUGE_THE_RAMFIST,\n            ID.mob.GOO_PAKE_THE_BLOODHOUND,\n            ID.mob.KEE_TAW_THE_NIGHTINGALE,\n            ID.mob.LAA_YAKU_THE_AUSTERE,\n            ID.mob.POO_YOZO_THE_BABBLER,\n        }\n\n        npcUtil.popFromQM(player, npc, mobs, { hide = 1 })\n    elseif csid == 49 then\n        player:setCharVar('moral', 7)\n    elseif csid == 50 then\n        if npcUtil.giveItem(player, xi.item.TSOO_HAJAS_HEADGEAR) then\n            player:setCharVar('moral', 8)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Bastok_Markets/npcs/Degenhard.lua"]={["Path"]="scripts/zones/Bastok_Markets/npcs/Degenhard.lua",["SHA256"]="7723539eaf85906d569fbcc6635b62c9a0d4c9397d240e62b1e2a0dc9152494c",["Text"]="-----------------------------------\n-- Area: Bastok Markets\n--  NPC: Degenhard\n-- Starts & Ends Quest: The Bare Bones\n-- Involved in Quests: Beat Around the Bushin\n-- !pos -175 2 -135 235\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.BEYOND_INFINITY) >= xi.questStatus.QUEST_ACCEPTED and\n        npcUtil.tradeHasExactly(trade, { xi.item.SEASONING_STONE, xi.item.FOSSILIZED_BONE, xi.item.FOSSILIZED_FANG })\n    then\n        player:startEvent(15)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.BEYOND_INFINITY) == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(14)\n    elseif player:getCharVar('BeatAroundTheBushin') == 3 then\n        player:startEvent(342)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 15 then\n        npcUtil.giveItem(player, xi.item.OLDE_RARAB_TAIL)\n        player:confirmTrade()\n    elseif csid == 342 then\n        player:setCharVar('BeatAroundTheBushin', 4)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Bastok_Markets/npcs/Lamepaue.lua"]={["Path"]="scripts/zones/Bastok_Markets/npcs/Lamepaue.lua",["SHA256"]="b5be40cddb2d2b1a0c4fa0acfe27f6db4c30ff0344e83d66cb73f44add403b7a",["Text"]="-----------------------------------\n-- Area: Bastok Markets\n--  NPC: Lamepaue\n-- Type: Past Event Watcher\n-- !pos -172.136 -5 -69.632 235\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    -- Bastok Missions.\n    local bastokMissions = 0xFFFFFFFE\n    if player:hasCompletedMission(xi.mission.log_id.BASTOK, xi.mission.id.bastok.FETICHISM) then\n        bastokMissions = bastokMissions - 2 -- Fetichism.\n    end\n\n    if player:hasCompletedMission(xi.mission.log_id.BASTOK, xi.mission.id.bastok.TO_THE_FORSAKEN_MINES) then\n        bastokMissions = bastokMissions - 4 -- To the Forsaken Mines.\n    end\n\n    -- Bastok Quests.\n    local bastokQuests = 0xFFFFFFFE\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_RETURN_OF_THE_ADVENTURER) then\n        bastokQuests = bastokQuests - 2     -- The Return of the Adventurer\n    end\n-- *Need the correct csid\n--     if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_FIRST_MEETING) then\n--         bastokQuests = bastokQuests - 4     -- The First Meeting\n--     end\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.WISH_UPON_A_STAR) then\n        bastokQuests = bastokQuests - 8     -- Wish Upon a Star (pt.1)\n        bastokQuests = bastokQuests - 16    -- Wish Upon a Star (pt.2)\n        bastokQuests = bastokQuests - 32    -- Wish Upon a Star (pt.3)\n    end\n\n-- *Need the correct csid/parameters\n--    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.ALL_BY_MYSELF) then\n--        bastokQuests = bastokQuests - 64    -- All by Myself\n--    end\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.ACHIEVING_TRUE_POWER) then\n        bastokQuests = bastokQuests - 128   -- Achieving True Power\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.TOO_MANY_CHEFS) then\n        bastokQuests = bastokQuests - 512   -- Too Many Chefs\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.A_PROPER_BURIAL) then\n        bastokQuests = bastokQuests - 1024  -- A Proper Burial (pt.1)\n        bastokQuests = bastokQuests - 2048  -- A Proper Burial (pt.2)\n        bastokQuests = bastokQuests - 4096  -- A Proper Burial (pt.3)\n        bastokQuests = bastokQuests - 8192  -- A Proper Burial (pt.4)\n        bastokQuests = bastokQuests - 16384 -- A Proper Burial (pt.5)\n        bastokQuests = bastokQuests - 32768 -- A Proper Burial (pt.6)\n    end\n\n    -- Other Quests.\n    local otherQuests = 0xFFFFFFFE\n    if player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.BEAT_AROUND_THE_BUSHIN) then\n        otherQuests = otherQuests - 2      -- Beat Around the Bushin\n    end\n\n    if player:hasCompletedQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.CONFESSIONS_OF_A_BELLMAKER) then\n        otherQuests = otherQuests - 4      -- Confessions of a Bellmaker\n    end\n\n    if player:hasCompletedQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.PICTURE_PERFECT) then\n        otherQuests = otherQuests - 8      -- Picture Perfect (pt.1)\n        otherQuests = otherQuests - 16     -- Picture Perfect (pt.2)\n        otherQuests = otherQuests - 32     -- Picture Perfect (pt.3)\n        otherQuests = otherQuests - 64     -- Picture Perfect (pt.4)\n    end\n\n    if player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.NO_STRINGS_ATTACHED) then\n        otherQuests = otherQuests - 128    -- No Strings Attached\n    end\n\n    if player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PUPPETMASTER_BLUES) then\n        otherQuests = otherQuests - 256    -- Puppetmaster Blues (pt.1)\n        otherQuests = otherQuests - 512    -- Puppetmaster Blues (pt.2)\n    end\n\n    if player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.COMEBACK_QUEEN) then\n        otherQuests = otherQuests - 1024   -- Comeback Queen\n    end\n\n-- *This quest, as of the time this script was written, is not yet defined.\n--     if player:hasCompletedQuest(**Unknown**, DANCER_ATTIRE) then\n--         otherQuests = otherQuests - 2048   -- Dancer Attire (pt.1)\n--         otherQuests = otherQuests - 4096   -- Dancer Attire (pt.2)\n--     end\n    if player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.DRAFTED_BY_THE_DUCHY) then\n        otherQuests = otherQuests - 8192   -- Drafted by the Duchy\n    end\n\n    if player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BATTLE_ON_A_NEW_FRONT) then\n        otherQuests = otherQuests - 16384  -- Battle on a New Front\n    end\n\n    if player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.VOIDWALKER_OP_126) then\n        otherQuests = otherQuests - 32768  -- VW Op. #126: Qufim Incursion\n    end\n\n-- *This quest, as of the time this script was written, is not yet defined.\n--     if player:hasCompletedQuest(**Unknown**, RECORDS_OF_EMINENCE) then\n--         otherQuests = otherQuests - 65536  -- Records of Eminence\n--     end\n\n-- *This quest, as of the time this script was written, is not yet defined.\n--     if player:hasCompletedQuest(**Unknown**, TRUST_MUMOR) then\n--         otherQuests = otherQuests - 131072 -- Trust (Mumor)\n--     end\n\n-- *This quest, as of the time this script was written, is not yet defined.\n--     if player:hasCompletedQuest(**Unknown**, UNITY_CONCORD) then\n--         otherQuests = otherQuests - 262144 -- Unity Concord (pt.1)\n--         otherQuests = otherQuests - 524288 -- Unity Concord (pt.2)\n--     end\n\n    -- Seekers of Adoulin\n    local seekersOfAdoulin = 0xFFFFFFFE\n-- *Need the correct csid\n--    if player:hasCompletedMission (xi.mission.log_id.SOA, xi.mission.id.soa.RUMORS_FROM_THE_WEST) then\n--        seekersOfAdoulin = seekersOfAdoulin - 2 -- Rumors from the West\n--    end\n\n    -- Determine if any cutscenes are available for the player.\n    local gil = player:getGil()\n    if\n        bastokMissions == 0xFFFFFFFE and\n        bastokQuests == 0xFFFFFFFE and\n        otherQuests == 0xFFFFFFFE and\n        seekersOfAdoulin == 0xFFFFFFFE\n    then -- Player has no cutscenes available to be viewed.\n        gil = 0 -- Setting gil to a value less than 10(cost) will trigger the appropriate response from this npc.\n    end\n\n    player:startEvent(326, bastokMissions, bastokQuests, otherQuests, seekersOfAdoulin, 0xFFFFFFFE, 0xFFFFFFFE, 10, gil)\nend\n\nentity.onEventUpdate = function(player, csid, option, npc)\n    if not player:delGil(10) then\n        player:setLocalVar('Lamepaue_PlayCutscene', 2)  -- Cancel the cutscene.\n        player:updateEvent(0)\n    else\n        player:setLocalVar('Lamepaue_PlayCutscene', 1)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if player:getLocalVar('Lamepaue_PlayCutscene') < 2 then\n        if option == 1 then        -- Fetichism.\n            player:startEvent(1008)\n        elseif option == 2 then        -- To the Forsaken Mines.\n            player:startEvent(1010)\n        elseif option == 33 then        -- The Return of the Adventurer\n            player:startEvent(243)\n--        elseif option == 34 then        -- The First Meeting\n--            player:startEvent(CSID)\n        elseif option == 35 then        -- Wish Upon a Star (pt.1)\n            player:startEvent(329)\n        elseif option == 36 then        -- Wish Upon a Star (pt.2)\n            player:startEvent(332)\n        elseif option == 37 then        -- Wish Upon a Star (pt.3)\n            player:startEvent(334)\n--        elseif option == 38 then        -- All by Myself\n--            player:startEvent(185)\n        elseif option == 39 then        -- Achieving True Power\n            player:startEvent(441)\n        elseif option == 40 then        -- Too Many Chefs\n            player:startEvent(411)\n        elseif option == 41 then        -- A Proper Burial (pt.1)\n            player:startEvent(475)\n        elseif option == 42 then        -- A Proper Burial (pt.2)\n            player:startEvent(477)\n        elseif option == 43 then        -- A Proper Burial (pt.3)\n            player:startEvent(479)\n        elseif option == 44 then        -- A Proper Burial (pt.4)\n            player:startEvent(481)\n        elseif option == 45 then        -- A Proper Burial (pt.5)\n            player:startEvent(483)\n        elseif option == 46 then        -- A Proper Burial (pt.6)\n            player:startEvent(485)\n        elseif option == 65 then        -- Beat Around the Bushin\n            player:startEvent(342)\n        elseif option == 66 then        -- Confessions of a Bellmaker\n            player:startEvent(402)\n-- Picture Perfect cutscenes need to be verified.\n        elseif option == 67 then        -- Picture Perfect (pt.1)\n            player:startEvent(403)\n        elseif option == 68 then        -- Picture Perfect (pt.2)\n            player:startEvent(404)\n        elseif option == 69 then        -- Picture Perfect (pt.3)\n            player:startEvent(405)\n        elseif option == 70 then        -- Picture Perfect (pt.4)\n            player:startEvent(406)\n        elseif option == 71 then        -- No Strings Attached\n            player:startEvent(434)\n        elseif option == 72 then        -- Puppetmaster Blues (pt.1)\n            player:startEvent(437)\n        elseif option == 73 then        -- Puppetmaster Blues (pt.2)\n            player:startEvent(439)\n        elseif option == 74 then        -- Comeback Queen\n            player:startEvent(490)\n--        elseif option == 75 then        -- Dancer Attire (pt.1)\n--            player:startEvent(CSID)\n--        elseif option == 76 then        -- Dancer Attire (pt.2)\n--            player:startEvent(CSID)\n-- Drafted by the Duchy and Battle on a New Front cutscenes need to be verified, ids may need to be changed or have additional parameters.\n        elseif option == 77 then        -- Drafted by the Duchy\n            player:startEvent(18)\n        elseif option == 78 then        -- Battle on a New Front\n            player:startEvent(12)\n        elseif option == 79 then        -- VW Op. #126: Qufim Incursion\n            player:startEvent(258)\n--        elseif option == 80 then        -- Records of Eminence\n--            player:startEvent(CSID)\n--        elseif option == 81 then        -- Trust (Mumor)\n--            player:startEvent(CSID)\n--        elseif option == 82 then        -- Unity Concord (pt.1)\n--            player:startEvent(CSID)\n--        elseif option == 83 then        -- Unity Concord (pt.2)\n--            player:startEvent(CSID)\n--        elseif option == 129 then        -- Rumors from the West\n--            player:startEvent(CSID)\n        end\n    end\n\n    player:setLocalVar('Lamepaue_PlayCutscene', 0)\nend\n\nreturn entity\n"},["scripts/zones/Bastok_Markets/npcs/Umberto.lua"]={["Path"]="scripts/zones/Bastok_Markets/npcs/Umberto.lua",["SHA256"]="e6868d1e1fc8e520a31ec5251d2d3e570109333851033b1da43b535d27180557",["Text"]="-----------------------------------\n-- Area: Bastok Markets\n--  NPC: Umberto\n-- Involved in Quest: Too Many Chefs\n-- !pos -56.896 -5 -134.267 235\n-----------------------------------\nlocal ID = zones[xi.zone.BASTOK_MARKETS]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if player:getCharVar('TOO_MANY_CHEFS') == 5 then -- end Quest Too Many Chefs\n        player:startEvent(473)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 473 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.AILEENS_DELIGHT)\n        else\n            player:addItem(xi.item.AILEENS_DELIGHT)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.AILEENS_DELIGHT)\n            player:addFame(xi.fameArea.BASTOK, 50)\n            player:setCharVar('TOO_MANY_CHEFS', 0)\n            player:completeQuest(xi.questLog.BASTOK, xi.quest.id.bastok.TOO_MANY_CHEFS)\n        end\n    end\nend\n\nreturn entity\n"}};
